const e={1:[["1","Başlangıçta Söz vardı ve Söz Tanrı'yla birlikteydi ve Söz Tanrı’ydı."],["2","O, başlangıçta Tanrı’yla birlikteydi."],["3","Her şey O’nun aracılığıyla oldu. Olmuş olanların hiçbiri O'nsuz olmadı."],["4","Hayat O’ndaydı ve hayat insanların ışığıydı."],["5","Işık karanlıkta parlar ve karanlık onu yenemedi."],["6","Tanrı tarafından gönderilen Yuhanna adlı bir adam geldi."],["7","O tanıklık amacıyla, ışık hakkında tanıklık edip herkes onun aracılığıyla iman etsin diye geldi."],["8","Kendisi ışık değildi, ama ışık hakkında tanıklık etsin diye gönderildi."],["9","Herkesi aydınlatan gerçek ışık dünyaya geldi."],["10","O, dünyadaydı, dünya O’nun aracılığıyla yaratıldı, ama dünya O’nu tanımadı."],["11","Kendininkilere geldi, ama kendininkiler O’nu kabul etmedi."],["12","Ancak kendisini kabul edip adına iman edenlerin hepsine, Tanrı’nın çocukları olma hakkını verdi."],["13","Onlar ne kandan, ne bedenin isteğinden ne de insan isteğinden değil, ama Tanrı’dan doğdular."],["14","Söz beden olup aramızda yaşadı. Biz O’nun yüceliğini, Baba’nın, lütuf ve gerçekle dolu biricik Oğlu’un yüceliğini gördük."],["15","Yuhanna O’nun hakkında tanıklık etti. Yüksek sesle şöyle dedi: “‘Benden sonra gelen benden üstündür. Çünkü O benden önce vardı’ dediğim kişi işte budur.”"],["16","O’nun doluluğundan hepimiz lütuf üzerine lütuf aldık."],["17","Çünkü Yasa Moşe aracılığıyla verildi. Lütuf ve gerçek Yeşua Mesih aracılığıyla gerçekleşti."],["18","Tanrı’yı hiç kimse hiçbir zaman görmedi. Baba’nın bağrında olan biricik Oğul O’nu ilan etti."],["19","Yahudiler Yuhanna’ya, “Sen kimsin?” diye sormak için Yeruşalem’den kâhinlerle Levililer’i gönderdiklerinde Yuhanna’nın tanıklığı şöyleydi."],["20","İnkâr etmeden açıkça, “Ben Mesih değilim” dedi."],["21","“Öyleyse kimsin? Eliya mısın?” diye sordular o da, “Değilim” dedi. “Sen o peygamber misin?” “Hayır” diye karşılık verdi."],["22","Bunun üzerine ona, “Sen kimsin? Bizi gönderenlere geri götürebileceğimiz bir yanıt ver. Kendin hakkında ne diyorsun?” dediler."],["23","Yuhanna, “Peygamber Yeşaya’nın dediği gibi, ‘Efendi’nin yolunu düzleyin’ diye çölde haykıranın sesiyim ben” dedi."],["24","Gönderilenler Ferisiler’dendi."],["25","Ona, “Eğer Mesih, Eliya ya da o peygamber değilsen, neden vaftiz ediyorsun?” diye sordular."],["26","Yuhanna onlara şu karşılığı verdi: “Ben suyla vaftiz ediyorum, ama aranızda tanımadığınız biri duruyor."],["27","Benden sonra gelen, benden üstündür. Ben O’nun çarığının bağını çözmeye layık değilim.”"],["28","Bu şeyler, Yuhanna’nın vaftiz ettiği Yarden'in ötesindeki Beytanya’da oldu."],["29","Yuhanna ertesi gün Yeşua’nın kendisine doğru geldiğini gördü ve şöyle dedi: “İşte, dünyanın günahını ortadan kaldıran Tanrı Kuzusu!"],["30","Kendisi için, ‘Benden sonra benden üstün biri geliyor, çünkü O benden önce vardı’ diye bildirdiğim kişi budur."],["31","Ben O’nu tanımıyordum, ama İsrael’in O’nu tanıması için suyla vaftiz ederek geldim.”"],["32","Yuhanna tanıklık edip dedi: “Ruh’un gökten güvercin gibi indiğini ve O’nun üzerinde durduğunu gördüm."],["33","Ben O’nu tanımıyordum, ama suyla vaftiz etmem için beni gönderen bana, ‘Ruh’un kimin üzerine inip durduğunu görürsen, Kutsal Ruh’ta vaftiz eden O’dur’ dedi."],["34","Ben de gördüm ve ‘Tanrı’nın Oğlu budur’ diye tanıklık ediyorum.”"],["35","Yine ertesi gün Yuhanna iki öğrencisiyle birlikte ayakta duruyordu."],["36","Yeşua yürürken Yuhanna O'na bakıp, “İşte, Tanrı Kuzusu!” dedi."],["37","Onun söylediğini duyan iki öğrenci Yeşua’nın ardından gittiler."],["38","Yeşua dönüp onların ardından geldiklerini görünce, “Ne arıyorsunuz?” dedi. O’na, “Rabbuni, nerede kalıyorsun?” dediler. ‘Rabbuni’ öğretmenim diye tercüme edilir."],["39","Onlara, “Gelin ve görün” dedi. Gelip O’nun nerede kaldığını gördüler ve o gün O’nunla kaldılar. Yaklaşık onuncu vakitti."],["40","Yuhanna’yı duyup Yeşua’nın ardından giden iki kişiden biri Simon Petrus’un kardeşi Andreas’tı."],["41","Andreas ilkin kendi kardeşi Simon’u buldu ve ona, “Mesih’i bulduk!” dedi. Mesih, meshedilmiş diye tercüme edilir."],["42","Onu Yeşua’ya götürdü. Yeşua ona baktı, “Sen Yuhanna oğlu Simon’sun. Adın Kefas olacak” dedi. Kefas kaya diye tercüme edilir."],["43","Yeşua, ertesi gün Galile’ye gitmeye karar verdi. Filipus’u bulup ona, “Ardımdan gel” dedi."],["44","Filipus, Andreas ve Petrus’un kenti olan Beytsayda’dandı."],["45","Filipus, Natanel’i buldu ve ona, “Moşe’nin Yasa’da bildirdiği ve peygamberlerin de hakkında yazdığı kişiyi, Yosef oğlu Nazaretli Yeşua’yı bulduk” dedi."],["46","Natanel ona, “Nazaret’den iyi bir şey çıkabilir mi?” dedi. Filipus ona, “Gel de gör” dedi."],["47","Yeşua, Natanel’in kendisine doğru geldiğini gördü ve onun hakkında, “İşte, kendisinde hile olmayan gerçek bir İsraelli!” dedi."],["48","Natanel O’na, “Beni nereden tanıyorsun?” dedi. Yeşua ona, “Filipus seni çağırmadan önce incir ağacının altındayken seni gördüm” dedi."],["49","Natanael O’na, “Rabbuni, sen Tanrı’nın Oğlu’sun! Sen İsrael’in Kralı’sın!” dedi."],["50","Yeşua ona, “Sana, ‘Seni incir ağacının altında gördüm’ dediğim için mi inanıyorsun? Bunlardan daha büyük şeyler göreceksin!” dedi."],["51","Ona, “Size doğrusunu söyleyeyim, bundan sonra göğün açıldığını ve Tanrı’nın meleklerinin İnsanoğlu’nun üzerine yükselip indiklerini göreceksiniz” dedi."]],2:[["1","Üçüncü gün, Galile’nin Kana Kenti'nde bir düğün vardı. Yeşua’nın annesi de oradaydı."],["2","Yeşua da öğrencileriyle birlikte düğüne davet edilmişti."],["3","Şarap tükenince Yeşua’nın annesi O’na, “Şarapları yok” dedi."],["4","Yeşua ona, “Kadın, bunun seninle benimle ne ilgisi var? Benim saatim henüz gelmedi” dedi."],["5","Annesi hizmetkârlara, “Size ne derse onu yapın” dedi."],["6","Orada Yahudiler’in geleneksel temizliği için koyulmuş, her biri seksen ile yüz yirmi litre su alan altı taş küp vardı."],["7","Yeşua onlara, “Küpleri suyla doldurun” dedi. Böylece küpleri ağzına kadar doldurdular."],["8","Onlara, “Şimdi biraz çıkarıp şölen başkanına götürün” dedi. Onlar da götürdüler."],["9","Şölen başkanı, şarap olmuş suyu tattığı zaman, bunun nereden geldiğini bilmiyordu ama suyu çıkarmış olan hizmetkârlar biliyordu. Şölen başkanı güveyi çağırdı."],["10","Ona, “Herkes önce iyi şarabı sunar, konuklar bol bol içtikten sonra da kötü olanı. Ama sen iyi şarabı şu ana dek sakladın!” dedi."],["11","Yeşua, bu ilk belirtisini Galile’nin Kana Kenti'nde yaptı ve yüceliğini gösterdi. Öğrencileri de O’na iman ettiler."],["12","Bundan sonra kendisi, annesi, kardeşleri ve öğrencileri Kafernahum’a gidip orada birkaç gün kaldılar."],["13","Yahudiler’in Pesah'ı yakındı ve Yeşua Yeruşalem’e çıktı."],["14","Yeşua sığır, koyun, güvercin satanları ve para bozanları tapınakta otururken buldu."],["15","İpten bir kamçı yaparak koyunları da sığırları da, hepsini tapınaktan kovdu. Para bozanların paralarını döküp masalarını devirdi."],["16","Güvercinleri satanlara, “Bunları buradan çıkarın! Babam’ın evini pazar yeri yapmayın!” dedi."],["17","Öğrencileri, “Senin evinin gayreti beni yiyip bitirecek” diye yazılmış olduğunu hatırladılar."],["18","Bunun üzerine Yahudiler O’na, “Bunları yaptığına göre bize nasıl bir belirti göstereceksin?” diye sordular."],["19","Yeşua onlara, “Bu tapınağı yıkın, üç gün içinde onu ayağa kaldıracağım” diye yanıtladı."],["20","Bunun üzerine Yahudiler, “Bu tapınağı bina etmek kırk altı yıl sürdü! Sen onu üç günde mi ayağa kaldıracaksın?”"],["21","Oysa Yeşua beden tapınağı için söylemişti."],["22","Bu nedenle Yeşua ölümden diriltildiğinde, öğrencileri O’nun bunu söylemiş olduğunu hatırladılar. Kutsal Yazı’ya ve Yeşua’nın söylemiş olduğu söze iman ettiler."],["23","Pesah'da, bayram sırasında, Yeruşalem’deyken, Yeşua’nın yaptığı belirtileri gören birçok kişi O’nun adına iman etti."],["24","Ama Yeşua bütün insanları bildiği için kendisi onlara güvenmiyordu."],["25","İnsana ilişkin kimsenin O’na tanıklık etmesine ihtiyacı yoktu. Çünkü insanda ne olduğunu O kendisi biliyordu."]],3:[["1","Yahudiler’in Ferisiler’den olan Nikodim adında bir önderi vardı."],["2","Geceleyin Yeşua’ya gelip, “Rabbuni, senin Tanrı’dan gelen bir öğretmen olduğunu biliyoruz. Çünkü Tanrı kendisiyle birlikte olmadıkça, hiç kimse senin yaptığın bu belirtileri yapamaz” dedi."],["3","Yeşua ona, “Sana doğrusunu söyleyeyim, bir kimse yeniden doğmadıkça, Tanrı’nın Krallığı'nı göremez” dedi."],["4","Nikodim O'na, “Yaşlanmış bir adam nasıl doğabilir? Annesinin rahmine ikinci kez girip doğabilir mi?” dedi."],["5","Yeşua şöyle yanıt verdi: “Sana doğrusunu söyleyeyim, bir kimse sudan ve Ruh’tan doğmadıkça, Tanrı’nın Krallığı'na giremez."],["6","Bedenden doğan bedendir. Ruh’tan doğan ruhtur."],["7","Sana, ‘Yeniden doğmalısın’ dediğime şaşma."],["8","Rüzgâr dilediği yerde eser, sesini duyarsın, ama nereden gelip nereye gittiğini bilemezsin. Ruh’tan doğan herkes de böyledir.”"],["9","Nikodim Yeşua’ya, “Bu şeyler nasıl olabilir?” diye karşılık verdi."],["10","Yeşua ona şöyle yanıt verdi: “Sen İsrael’in öğretmeniyken bu şeyleri anlamıyor musun?"],["11","Sana doğrusunu söyleyeyim, biz bildiğimizi söylüyoruz, gördüğümüze tanıklık ediyoruz ve siz bizim tanıklığımızı kabul etmiyorsunuz."],["12","Size yeryüzüyle ilgili şeyleri söylediğimde inanmazsanız, gökle ilgili şeyleri söylediğimde nasıl inanacaksınız?"],["13","Gökten inmiş olan, İnsanoğlu’ndan başka kimse göğe çıkmamıştır; O ki, göktedir."],["14","Moşe çölde yılanı nasıl yukarı kaldırdıysa, İnsanoğlu da öyle yukarı kaldırılmalıdır."],["15","Öyle ki, O’na iman eden hiç kimse mahvolmasın, ancak sonsuz hayata sahip olsun."],["16","Çünkü Tanrı dünyayı o kadar sevdi ki, biricik Oğlu’nu verdi. Öyle ki, O’na iman eden hiç kimse mahvolmasın, ancak sonsuz hayata sahip olsun."],["17","Çünkü Tanrı, Oğlu’nu dünyayı yargılamak için dünyaya göndermedi. Dünya O’nun aracılığıyla kurtulsun diye gönderdi."],["18","O’na iman eden yargılanmaz. İman etmeyen zaten yargılanmıştır, çünkü Tanrı’nın biricik Oğlu’nun adına iman etmemiştir."],["19","Yargı da şudur: Dünyaya ışık geldi, ama insanlar ışıktan çok karanlığı sevdiler. Çünkü işleri kötüydü."],["20","Çünkü kötülük yapan herkes ışıktan nefret eder ve yaptıkları açığa çıkmasın diye ışığa gelmez."],["21","Ama gerçeği yerine getiren kişi, işlerinin Tanrı’da yapıldığı ortaya çıksın diye ışığa gelir.”"],["22","Bundan sonra Yeşua, öğrencileriyle birlikte Yahudiye diyarına geldi. Orada onlarla kaldı ve vaftiz etti."],["23","Yuhanna da Salim yakınlarındaki Aynon’da vaftiz ediyordu. Çünkü orada çok su vardı. Birçokları gelip vaftiz oldular."],["24","Yuhanna henüz hapse atılmamıştı."],["25","Yuhanna’nın öğrencileriyle bazı Yahudiler arasında temizlenme konusunda bir tartışma çıktı."],["26","Onlar Yuhanna’ya gelip ona şöyle dediler: “Rabbuni, Yarden'in ötesinde birlikte olduğun ve kendisi için tanıklık ettiğin kişi, işte, O vaftiz ediyor ve herkes O’na gidiyor.”"],["27","Yuhanna şöyle yanıt verdi: “İnsan kendisine gökten verilmedikçe hiçbir şey alamaz."],["28","‘Ben Mesih değilim, O’nun öncüsü olarak gönderildim’ dediğime siz kendiniz tanıksınız."],["29","Gelin kiminse güvey odur. Ama güveyin yanında duran ve onu dinleyen dostu, güveyin sesinden çok sevinir. Böylece benim sevincim tamam oldu."],["30","O yükselmeli, bense küçülmeliyim."],["31","Yukarıdan gelen herkesten üstündür. Yeryüzünden gelen, yeryüzüne aittir ve yeryüzünden söz eder. Gökten gelen herkesten üstündür."],["32","Gördüğüne, duyduğuna tanıklık eder; ama hiç kimse O’nun tanıklığını kabul etmez."],["33","O’nun tanıklığını kabul eden, Tanrı’nın gerçek olduğuna mührünü basmıştır."],["34","Çünkü Tanrı’nın gönderdiği kişi Tanrı’nın sözlerini söyler. Çünkü Tanrı, Ruh’u ölçüsüz verir."],["35","Baba Oğul’u sever ve her şeyi O’nun eline vermiştir."],["36","Oğul’a iman edenin sonsuz hayatı vardır. Ama Oğul’un sözüne itaat etmeyen hayatı görmeyecektir. Tanrı’nın gazabı ise onun üzerinde kalır.”"]],4:[["1","Efendi, Ferisiler’in, Yeşua’nın Yuhanna’dan daha çok öğrenci topladığını ve vaftiz ettiğini duyduğunu öğrendi."],["2","Oysa Yeşua’nın kendisi değil, ama öğrencileri vaftiz ediyorlardı."],["3","Yeşua Yahudiye’den ayrılıp Galile’ye gitti."],["4","Samariya’dan geçmesi gerekiyordu."],["5","Böylece Samariya’nın Sihar denilen kentine geldi. Burası Yakov’un kendi oğlu Yosef’e vermiş olduğu toprağın yakınındaydı."],["6","Yakov’un kuyusu oradaydı. Yolculuktan yorulmuş olan Yeşua kuyunun yanına oturdu. Altıncı vakit sularıydı."],["7","Samariyalı bir kadın su çekmeye geldi. Yeşua ona, “Bana su ver içeyim” dedi."],["8","Çünkü öğrencileri yiyecek almak için kente gitmişti."],["9","Samariyalı kadın O’na, “Sen bir Yahudi’sin. Nasıl olur da benden, Samariyalı bir kadından su istersin?” dedi. Yahudiler’in Samariyalılar’la ilişkileri yoktur."],["10","Yeşua ona, “Eğer sen Tanrı’nın armağanını ve sana, ‘Bana su ver, içeyim’ diyenin kim olduğunu bilseydin, sen O’ndan isterdin, O da sana hayat suyunu verirdi” dedi."],["11","Kadın O’na, “Efendim, su çekecek bir şeyin yok, kuyu da derin” dedi. “Peki bu hayat suyunu nereden bulacaksın?"],["12","Sen, bu kuyuyu bize veren, kendisi, çocukları ve sığırları ondan içmiş olan atamız Yakov’tan daha mı büyüksün?”"],["13","Yeşua ona şu karşılığı verdi: “Bu sudan her içen yine susar."],["14","Ama benim vereceğim sudan içen bir daha asla susamaz. Benim vereceğim su, içende sonsuz hayat için fışkıran bir kaynak olacak.”"],["15","Kadın O'na, “Efendim, bu suyu bana ver ki, bir daha susamayayım, ne de buraya kadar su çekmeye geleyim” dedi."],["16","Yeşua ona, “Git, kocanı çağır ve buraya gel” dedi."],["17","Kadın, “Kocam yok” diye yanıtladı. Yeşua ona, “Kocam yok demekle iyi söyledin."],["18","Çünkü beş kocaya vardın ve şimdi sende olan kocan değildir. Bununla gerçeği söyledin” dedi."],["19","Kadın O’na, “Efendim, anlıyorum ki, sen bir peygambersin."],["20","Atalarımız bu dağda tapındılar ve siz Yahudiler, tapınılması gereken yerin Yeruşalem’de olduğunu söylüyorsunuz.”"],["21","Yeşua ona şöyle dedi: “Kadın, inan bana, öyle bir vakit geliyor ki, Baba’ya ne bu dağda, ne de Yeruşalem’de tapınacaksınız!"],["22","Siz bilmediğinize tapıyorsunuz. Biz bildiğimize tapıyoruz. Çünkü kurtuluş Yahudiler’dendir."],["23","Ama doğru tapınanların Baba’ya ruhta ve gerçekte tapınacakları saat geliyor ve şimdidir. Çünkü Baba kendisine böyle tapınanları arıyor."],["24","Tanrı ruhtur, O’na tapınanlar ruhta ve gerçekte tapınmaları gerektir.”"],["25","Kadın O’na, “Mesih denen meshedilmiş Olan’ın geleceğini biliyorum” dedi. “Geldiği zaman bize her şeyi bildirecek.”"],["26","Yeşua ona, “Seninle konuşan ben, O’yum” dedi."],["27","Bunun üzerine öğrencileri geldi. Bir kadınla konuşmakta olmasına şaştılar. Yine de hiçbiri “Ne arıyordun?” ya da “Neden o kadınla konuşuyordun?” diye sormadı."],["28","Böylece kadın su testisini bırakıp kente gitti ve halka şöyle dedi:"],["29","“Gelin, yaptığım her şeyi bana söyleyen adamı görün. Acaba bu Mesih olabilir mi?”"],["30","Onlar da kentten çıkıp Yeşua’ya geliyordu."],["31","Bu arada öğrenciler, “Rabbuni, ye” diye ısrar ettiler."],["32","Ama O onlara, “Benim sizin bilmediğiniz bir yiyeceğim var” dedi."],["33","Bunun üzerine öğrenciler birbirlerine, “Acaba biri O’na yiyecek mi getirdi?” dediler."],["34","Yeşua onlara, “Benim yemeğim, beni gönderenin isteğini yerine getirmek ve O’nun işini tamamlamaktır” dedi."],["35","“‘Hasata daha dört ay var’ demiyor musunuz? İşte, size söylüyorum, gözlerinizi kaldırın da hasat için çoktan ağarmış olan tarlalara bakın."],["36","Biçen ücretini alır ve sonsuz hayat için ürün toplar. Öyle ki, eken de, biçen de birlikte sevinsinler."],["37","Çünkü, ‘Biri eker, diğeri biçer’ sözü bunda doğrudur."],["38","Ben sizi, emek vermediğiniz şeyi biçmeye gönderdim. Başkaları emek verdiler, siz de onların emeğine girdiniz.”"],["39","O kentten birçok Samariyalı, “Yaptığım her şeyi bana söyledi” diye tanıklık eden kadının sözünden dolayı O’na iman etti."],["40","Samariyalılar yanına gelip yanlarında kalması için O’na yalvardılar. O da orada iki gün kaldı."],["41","Daha birçokları O’nun sözünden dolayı iman ettiler."],["42","Kadına, “Bizim iman etmemizin nedeni artık senin konuşman değil” dediler. “Çünkü kendimiz duyduk ve gerçekten dünyanın Kurtarıcısı olan Mesih'in bu olduğunu biliyoruz.”"],["43","İki gün sonra Yeşua oradan çıkıp Galile’ye gitti."],["44","Çünkü Yeşua’nın kendisi, bir peygamberin kendi ülkesinde saygınlığı olmadığına tanıklık etmişti."],["45","Böylece Galile’ye geldiğinde, bayramda Yeruşalem’de yaptığı her şeyi gören Galileliler O’nu kabul ettiler. Çünkü onlar da bayrama gitmişlerdi."],["46","Yeşua, suyu şarap yaptığı Galile’nin Kana Kenti'ne yeniden geldi. Oğlu Kafernahum’da hasta olan soylu bir adam vardı."],["47","Adam Yeşua’nın Yahudiye’den Galile’ye geldiğini duyunca yanına gitti. Ölüm döşeğinde yatan oğlunu inip iyileştirmesi için O’na yalvardı."],["48","Yeşua ona, “Belirtiler ve harikalar görmedikçe, asla iman etmeyeceksiniz” dedi."],["49","Soylu adam O’na, “Efendim, çocuğum ölmeden in” dedi."],["50","Yeşua ona, “Yoluna git, oğlun yaşıyor” dedi. Adam, Yeşua’nın kendisine söylediği söze inandı ve yoluna gitti."],["51","O daha yoldan inerken, hizmetkârları onu karşıladılar ve “Çocuğun yaşıyor!” dediler."],["52","Oğlunun iyileşmeye başladığı saati onlara sordu. “Dün yedinci vakitte ateş onu bıraktı” dediler."],["53","O zaman baba bunun, Yeşua’nın kendisine, “Oğlun yaşıyor” dediği saat olduğunu anladı. Kendisi ve tüm ev halkı iman etti."],["54","Bu, Yeşua’nın Yahudiye’den Galile’ye gelişinde yaptığı ikinci belirtiydi."]],5:[["1","Bu şeylerden sonra Yahudiler’in bir bayramı vardı ve Yeşua Yeruşalem’e çıktı."],["2","Yeruşalem’de Koyun Kapısı’nın yanında, İbranice'de Beytesta denilen, beş verandası olan bir havuz vardı."],["3","Bunların içinde, suyun çalkalanmasını bekleyen hasta, kör, topal ya da felçli çok sayıda insan yatardı."],["4","Çünkü bir melek belirli zamanlarda havuza iner ve suyu çalkalardı. Suyun çalkalanmasından sonra havuza ilk giren hastalığı ne olursa olsun iyileşirdi."],["5","Orada otuz sekiz yıldır hasta olan bir adam vardı."],["6","Yeşua onu orada yatmakta görünce, uzun zamandır hasta olduğunu da bilerek ona, “İyileşmek ister misin?” diye sordu."],["7","Hasta adam O'na, “Efendim, su çalkalandığında beni havuza indirecek kimsem yok, ben gelmekte iken başka biri benden önce iniyor” dedi."],["8","Yeşua ona, “Kalk, yatağını topla ve yürü” dedi."],["9","Adam hemen iyileşti ve yatağını kaldırıp yürüdü. O gün Şabat'dı."],["10","Yahudiler iyileşen adama, “Bugün Şabat” dediler. “Yatağını toplaman Yasa’ya uygun değil.”"],["11","Adam onlara şu karşılığı verdi: “Beni iyileştiren, bana, ‘Yatağını topla ve yürü’ dedi.”"],["12","Sonra ona, “Sana, ‘Yatağını topla ve yürü’ diyen adam kim?” diye sordular."],["13","Ama iyileşen adam O’nun kim olduğunu bilmiyordu. Bulunduğu yer kalabalıktı, Yeşua da çekilmişti."],["14","Sonra Yeşua adamı tapınakta buldu. Ona, “İşte, iyileştin. Daha fazla günah işleme de, sana daha kötü bir şey olmasın” dedi."],["15","Adam gidip kendisini iyileştirenin Yeşua olduğunu Yahudi yetkililere bildirdi."],["16","Bu nedenle Yahudi yetkililer Yeşua’ya zulmettiler ve O’nu öldürmenin bir yolunu aradılar. Çünkü Şabat'da bu şeyleri yapıyordu."],["17","Ama Yeşua onlara, “Babam hâlâ çalışıyor, bu yüzden ben de çalışıyorum” dedi."],["18","Bu nedenle Yahudi yetkililer O’nu daha da çok öldürmek istediler. Çünkü yalnızca Şabat’ı bozmakla kalmamış, Tanrı’nın kendi Babası olduğunu da söyleyerek kendisini Tanrı’yla bir tutmuştu."],["19","Yeşua onlara şu karşılığı verdi: “Size doğrusunu söyleyeyim, Oğul, kendiliğinden hiçbir şey yapamaz. Ancak Baba’nın yaptıklarını görüp onları yapar. Baba ne şeyler yaparsa Oğul da bunların aynısını yapar."],["20","Çünkü Baba, Oğul’u sever ve kendisinin yaptığı her şeyi O’na gösterir. Şaşasınız diye O’na bunlardan daha büyük işler gösterecektir."],["21","Baba nasıl ölüleri diriltip onlara hayat veriyorsa, Oğul da dilediklerine hayat verir."],["22","Çünkü Baba kimseyi yargılamaz, ama bütün yargıyı Oğul’a vermiştir."],["23","Öyle ki, herkes Baba’ya saygı duyduğu gibi, Oğul’a da saygı duysun. Oğul’a saygı duymayan, O’nu gönderen Baba’ya da saygı duymaz.”"],["24","“Size doğrusunu söyleyeyim, sözümü işitip beni gönderene iman edenin sonsuz hayatı vardır ve yargı içine girmez, ama ölümden hayata geçmiştir."],["25","Size doğrusunu söyleyeyim, ölülerin Tanrı Oğlu’nun sesini duyacakları ve duyanların yaşayacakları saat geliyor, geldi bile."],["26","Baba’nın kendisinde hayat olduğu gibi, böylece kendisinde hayat olmasını Oğul'a da verdi."],["27","O, İnsanoğlu olduğu için O’na yargılama yetkisi de verdi."],["28","Buna şaşmayın, çünkü mezarlarda olanların hepsinin O’nun sesini duyacakları saat geliyor."],["29","İyilik yapanlar yaşamak için dirilişe, kötülük yapanlar yargıya çıkacaklardır."],["30","Ben kendiliğimden hiçbir şey yapamam. Duyduğum gibi yargılarım ve yargım doğrudur. Çünkü ben kendi isteğimi değil, beni gönderen Babam’ın isteğini ararım."],["31","“Kendim hakkında tanıklık edersem, tanıklığım geçerli olmaz."],["32","Benim hakkımda tanıklık eden başka biri vardır. O’nun benim hakkımdaki tanıklığının doğru olduğunu bilirim."],["33","Yuhanna’ya adamlar gönderdiniz, o da gerçeğe tanıklık etti."],["34","Ama benim almış olduğum tanıklık insandan değil. Ancak bunları siz kurtulasınız diye söylüyorum."],["35","O, yanan ve parlayan bir kandildi ve sizler bir süre onun ışığında sevinmek istediniz."],["36","Ama benim tanıklığım Yuhanna’nınkinden daha üstündür. Çünkü Baba’nın tamamlamam için bana verdiği işler, yaptığım şu işler, beni Baba’nın gönderdiğine tanıklık ediyor."],["37","Beni gönderen Baba’nın kendisi benim için tanıklık etti. Hiçbir zaman ne O’nun sesini duydunuz ne de biçimini gördünüz."],["38","O’nun sözü içinizde yaşamıyor. Çünkü gönderdiği kişiye iman etmiyorsunuz.”"],["39","“Kutsal Yazılar’ı araştırıyorsunuz. Çünkü sonsuz hayatınızın onlarda olduğunu sanıyorsunuz. Benim hakkımda tanıklık eden de onlardır."],["40","Yine de hayat bulmak için bana gelmek istemiyorsunuz."],["41","İnsanlardan övgü kabul etmiyorum."],["42","Ama sizi tanıyorum ve kendinizde Tanrı sevgisi yoktur."],["43","Babam’ın adıyla geldim ve beni kabul etmiyorsunuz. Ama başka biri kendi adıyla gelse, onu kabul edeceksiniz."],["44","Birbirinizden övgüler kabul eden ve tek olan Tanrı’nın övgüsünü aramayan sizler bana nasıl iman edebilirsiniz?”"],["45","“Sizi Baba’nın önünde suçlayacağımı sanmayın. Sizi suçlayan umut bağladığınız Moşe’dir."],["46","Moşe’ye iman etmiş olsaydınız, bana da iman ederdiniz. Çünkü o benim hakkımda yazmıştır."],["47","Ama onun yazdıklarına iman etmezseniz, benim sözlerime nasıl iman edeceksiniz?”"]],6:[["1","Bu şeylerden sonra Yeşua, Taberiye Denizi olarak da adlandırılan Galile Denizi’nin karşı yakasına gitti."],["2","Büyük bir kalabalık O’nu izliyordu. Çünkü O’nun hastalar üzerinde yapmış olduğu belirtileri görmüşlerdi."],["3","Yeşua dağa çıkıp orada öğrencileriyle birlikte oturdu."],["4","Yahudiler’in Pesah Bayramı yakındı."],["5","Bu nedenle Yeşua gözlerini kaldırıp büyük bir topluluğun kendisine doğru geldiğini görünce Filipus’a, “Bunlar yesin diye nereden ekmek satın alalım?” dedi."],["6","Bunu onu sınamak için söyledi, çünkü ne yapacağını kendisi biliyordu."],["7","Filipus O’na, “Her biri biraz alsın diye iki yüz dinarlık ekmek bile onlara yetmez” diye yanıt verdi."],["8","Öğrencilerinden biri, Simon Petrus’un kardeşi Andreas O’na şöyle dedi:"],["9","“Burada beş arpa ekmeği ve iki balığı olan bir çocuk var. Ama bu kadar çok insana bunlar nedir?”"],["10","Yeşua, “İnsanları yere oturtun” dedi. O yerde bol çayır vardı. Böylece insanlar yere oturdu, yaklaşık beş bin erkek vardı."],["11","Yeşua ekmekleri aldı, şükrettikten sonra öğrencilerine dağıttı ve öğrenciler de halka dağıttı. Aynı şekilde balıklardan da istedikleri kadar verdi."],["12","Onlar doyduktan sonra Yeşua öğrencilerine, “Artakalan parçaları toplayın, hiçbir şey kaybolmasın” dedi."],["13","Böylece onları topladılar. Beş arpa ekmeği yiyenlerden artakalan parçalarla on iki sepet doldurdular."],["14","Bu nedenle halk, Yeşua’nın yapmış olduğu belirtiyi görünce, “Gerçekten dünyaya gelecek olan peygamber budur” dediler."],["15","Bu nedenle Yeşua, onların gelip kendisini kral yapmak üzere zorla götüreceklerini bildiği için yalnız başına yine dağa çekildi."],["16","Akşam olunca öğrencileri denize indiler."],["17","Bir tekneye girip denizin karşı yakasındaki Kafernahum’a gidiyorlardı. Artık hava kararmış, Yeşua henüz yanlarına gelmemişti."],["18","Büyük bir rüzgârdan deniz kabardı."],["19","Böylece öğrenciler yirmi beş ya da otuz stadia kadar kürek çektikten sonra, Yeşua’nın denizin üstünde yürüyerek tekneye yaklaştığını gördüler. Korkuya kapıldılar."],["20","Ama onlara, “Benim, korkmayın” dedi."],["21","Bunun üzerine O’nu tekneye almak istediler. Tekne hemen gitmekte oldukları karaya ulaştı."],["22","Ertesi gün denizin öbür kıyısında duran kalabalık, orada öğrencilerinin bindiği tekneden başka tekne olmadığını ve Yeşua’nın öğrencileriyle birlikte tekneye girmediğini gördü. Öğrenciler ise yalnız gitmişlerdi."],["23","Ancak Efendi’nin şükretmesinden sonra halkın yemek yediği yerin yakınına Taberiye’den tekneler geldi."],["24","Kalabalık, Yeşua’nın ve öğrencilerinin orada olmadığını görünce, teknelere binip Yeşua’yı aramak için Kafernahum’a geldiler."],["25","O’nu denizin karşı yakasında bulduklarında, “Rabbuni, buraya ne zaman geldin?” diye sordular."],["26","Yeşua onlara şu karşılığı verdi: “Size doğrusunu söyleyeyim, beni belirtiler gördüğünüz için değil, ekmeklerden yiyip doyduğunuz için arıyorsunuz."],["27","Çürüyen yiyecek için değil, İnsanoğlu’nun size vereceği sonsuz hayat boyunca kalan yiyecek için çalışın. Çünkü Baba Tanrı O’na mührünü basmıştır.”"],["28","Bu nedenle O’na, “Tanrı’nın işlerini işlemek için ne yapmalıyız?” dediler."],["29","Yeşua onlara, “Tanrı’nın işi, O’nun gönderdiği kişiye iman etmenizdir” diye yanıtladı."],["30","Bunun üzerine O’na, “Öyleyse görüp sana iman edelim diye nasıl bir belirti yapacaksın? Ne iş yapacaksın?” dediler."],["31","“Atalarımız çölde man yediler. Yazılmış olduğu gibi, ‘Yemeleri için onlara gökten ekmek verdi.’”"],["32","Yeşua bunun üzerine onlara şöyle dedi: “Size doğrusunu söyleyeyim, size gökten ekmeği Moşe vermedi, gökten size gerçek ekmeği Babam verdi."],["33","Çünkü Tanrı’nın ekmeği gökten inen ve dünyaya hayat verendir.”"],["34","Bunun üzerine O’na, “Efendimiz, bu ekmeği bize her zaman ver” dediler."],["35","Yeşua onlara, “Hayat ekmeği Ben’im. Bana gelen acıkmaz ve bana iman eden asla susamaz” dedi."],["36","“Beni gördüğünüzü söyledim ama yine de iman etmiyorsunuz."],["37","Baba’nın bana verdiklerinin hepsi bana gelecek. Bana geleni, hiçbir zaman dışarı atmam."],["38","Çünkü ben kendi isteğimi değil, beni gönderenin isteğini yapmak için gökten indim."],["39","Beni gönderen Babam’ın isteği şudur ki, bana verdiklerinden hiçbirini kaybetmeyeyim, son günde hepsini dirilteyim."],["40","Beni gönderenin isteği şudur, Oğul’u gören ve O’na iman eden herkesin sonsuz hayatı olsun. Ben de onu son günde dirilteceğim.”"],["41","Bunun üzerine Yahudiler, “Gökten inen ekmek Ben’im” dediği için Yeşua’ya karşı söylenip dediler."],["42","“Babasını ve annesini tanıdığımız, Yosef’in oğlu Yeşua değil mi bu? O zaman nasıl oluyor da ‘Gökten indim’ diyor?”"],["43","Bu nedenle Yeşua onlara, “Aranızda söylenmeyin."],["44","Beni gönderen Babam bir kimseyi bana çekmedikçe kimse bana gelemez. Ben de o kişiyi son günde dirilteceğim."],["45","Peygamberlerde, ‘Hepsi Tanrı tarafından eğitilicek’ diye yazılıdır. Bu nedenle, Baba’yı işiten ve O’ndan öğrenen herkes bana gelir."],["46","Baba’yı kimse görmüş demek değildir, Baba’yı yalnızca Tanrı’dan olan görmüştür."],["47","Size doğrusunu söyleyeyim, bana iman edenin sonsuz hayatı vardır."],["48","Hayat ekmeği Ben’im."],["49","Atalarınız çölde man yediler ve öldüler."],["50","İşte, ondan yiyenler ölmesin diye gökten inmiş olan hayat ekmeği budur."],["51","Gökten inmiş olan diri ekmek benim. Kim bu ekmekten yerse, sonsuza dek yaşayacak. Evet, dünyanın hayatı için vereceğim ekmek benim bedenimdir” dedi."],["52","Bunun üzerine Yahudiler, “Bu adam yememiz için bedenini bize nasıl verebilir?” diyerek birbirleriyle çekiştiler."],["53","Yeşua bunun için onlara şöyle dedi: “Size doğrusunu söyleyeyim, İnsanoğlu’nun bedenini yiyip O'nun kanını içmedikçe, sizde hayat olmaz."],["54","Bedenimi yiyip kanımı içenin sonsuz hayatı vardır, ben de onu son günde dirilteceğim."],["55","Çünkü benim bedenim gerçek yiyecek, kanım gerçek içecektir."],["56","Bedenimi yiyip kanımı içen bende yaşar, ben de onda."],["57","Diri olan Baba’nın beni gönderdiği, benim de O’nun sayesinde yaşadığım gibi, beni yiyen de benim sayemde yaşayacaktır."],["58","Gökten inen ekmek budur. Atalarınızın yiyip öldüğü man gibi değildir. Bu ekmeği yiyen sonsuza dek yaşar.”"],["59","Yeşua bunları Kafernahum’da havrada öğretirken söyledi."],["60","Bunun üzerine öğrencilerinden birçoğu bunu duyunca, “Bu söz ağırdır! Onu kim duyabilir?” dediler."],["61","Yeşua içinden öğrencilerinin buna söylendiklerini bilerek, onlara şöyle dedi, “Bu sizin tökezlemenize mi neden oluyor?” dedi."],["62","“Ya eğer İnsanoğlu’nun önceden bulunduğu yere yükseldiğini görseydiniz?"],["63","Hayat veren Ruh’tur. Beden hiçbir fayda sağlamaz. Size söylediğim sözler ruhtur ve hayattır."],["64","Ama içinizde iman etmeyenler de var.” Çünkü Yeşua, iman etmeyenlerin ve kendisine ihanet edecek olanın kim olduğunu başından beri biliyordu."],["65","“Bu nedenle size demiştim, Baba'dan kendisine verilmedikçe hiç kimse bana gelemez” dedi."],["66","Bunun üzerine öğrencilerinin çoğu geri döndü ve artık O’nunla yürümez oldu."],["67","Yeşua bu nedenle Onikiler’e, “Siz de mi gitmek istiyorsunuz?” dedi."],["68","Simon Petrus O’na, “Efendimiz, kime gidelim? Sonsuz hayatın sözleri sendedir."],["69","Senin diri Tanrı’nın Oğlu Mesih olduğuna iman ettik ve bunu biliyoruz” diye karşılık verdi."],["70","Yeşua onlara şöyle yanıt verdi: “Siz Onikiler’i ben seçmedim mi? Yine de biriniz iblis değil mi?”"],["71","Simon İskariot’un oğlu Yahuda’dan söz ediyordu. Çünkü kendisine ihanet edecek olan Onikiler’den birisi oydu."]],7:[["1","Bu şeylerden sonra Yeşua Galile’de dolaşıyordu. Çünkü Yahudiler O’nu öldürmeye çalıştıkları için Yahudiye’de dolaşmak istemiyordu."],["2","O sırada Yahudiler’in Çardak Bayramı yakındı."],["3","Bu nedenle kardeşleri O’na, “Buradan ayrıl ve Yahudiye’ye git, öğrencilerin de yaptığın işleri görsünler” dediler."],["4","“Çünkü kendini açıkça tanıtmak isteyen biri gizlice yapmaz. Eğer bu şeyleri yapıyorsan kendini dünyaya göster.”"],["5","Kardeşleri bile O’na iman etmiyordu."],["6","Bu nedenle Yeşua onlara, “Benim zamanım daha gelmedi, ama sizin için zaman hep uygundur” dedi."],["7","“Dünya sizden nefret edemez, ama benden nefret ediyor. Çünkü ben dünya hakkında, işlerinin kötü olduğuna tanıklık ediyorum."],["8","Siz bayrama çıkın. Ben henüz çıkmayacağım. Çünkü zamanım henüz dolmadı.”"],["9","Yeşua bunları onlara söyledikten sonra Galile’de kaldı."],["10","Ama kardeşleri bayrama çıkınca, O da çıktı. Ama açıkça değil, gizlice idi."],["11","Bu nedenle Yahudiler bayramda O’nu arayıp, “Nerede O?” diyorlardı."],["12","Kalabalıklar arasında O’nun hakkında çok söylenti vardı. Bazıları, “O iyi bir adamdır” diyordu. Bazıları ise, “Öyle değil, ama halkı saptırıyor” diyorlardı."],["13","Yine de Yahudiler'den korktukları için kimse O’nun hakkında açıkça konuşmuyordu."],["14","Artık Bayramın ortası olunca, Yeşua tapınağa çıkıp öğretiyordu."],["15","Bunun üzerine Yahudiler, “Hiç eğitim görmemiş bu adam, yazıları nasıl biliyor?” diyerek şaştılar."],["16","Yeşua onlara şu karşılığı verdi: “Benim öğretim benim değil, beni gönderenindir."],["17","Kim Tanrı’nın isteğini yerine getirmek isterse, öğretimin Tanrı’dan mı olduğunu, yoksa kendiliğimden mi konuştuğumu bilecektir."],["18","Kendiliğinden konuşan kendi yüceliğini arar, ama kendisini göndereni yüceltmek isteyen doğrudur ve O’nda haksızlık yoktur."],["19","Moşe size Yasa’yı vermedi mi? Oysa hiçbiriniz Yasa’yı tutmuyorsunuz. Neden beni öldürmeye çalışıyorsunuz?”"],["20","Kalabalık, “Sende iblis var! Kim seni öldürmeye çalışıyor?” diye karşılık verdi."],["21","Yeşua onlara şöyle yanıt verdi: “Ben bir iş yaptım, hepiniz onun yüzünden şaştınız."],["22","Moşe size sünneti verdi - ki Moşe’den değil, atalardandır - Şabat'da bir erkek çocuğu sünnet ediyorsunuz."],["23","Madem Moşe’nin Yasası bozulmasın diye Şabat'da bir erkek çocuğu sünnet ediyorsunuz da, Şabat'da bir adamı tamamen sağlıklı ettim diye bana neden kızıyorsunuz?"],["24","Dış görünüşe göre yargılamayın, ama doğru yargılayın.”"],["25","Bunun üzerine Yeruşalem’den bazıları, “Öldürmeye çalıştıkları adam bu değil mi?” dediler."],["26","“İşte, açıkça konuşuyor ve O’na hiçbir şey söylemiyorlar. Yoksa önderler O’nun gerçekten Mesih olduğunu bildiler mi?"],["27","Ama biz bu adamın nereden geldiğini biliyoruz. Oysa Mesih geldiğinde kimse O’nun nereden geldiğini bilmeyecek.”"],["28","Yeşua bunun üzerine tapınakta yüksek sesle öğretip şöyle söyledi: “Hem beni tanıyorsunuz, hem de nereden geldiğimi biliyorsunuz. Ben kendiliğimden gelmedim. Ama beni gönderen gerçektir. Siz O’nu tanımıyorsunuz."],["29","Ben O’nu tanıyorum, çünkü ben O’ndanım ve beni O gönderdi.”"],["30","Bunun üzerine Yeşua’yı tutmak istediler, ama saati henüz gelmediği için kimse O’na el sürmedi."],["31","Kalabalıktan birçok kişi O’na iman etti. “Mesih geldiği zaman, bu adamın yaptığı belirtilerden daha fazlasını mı yapacak?” diyorlardı."],["32","Ferisiler, kalabalığın Yeşua hakkında bu şekilde fısıldaştıklarını duydular. Başkâhinlerle Ferisiler O’nu tutuklamak için görevliler gönderdiler."],["33","O zaman Yeşua, “Bir süre daha sizinleyim, sonra beni gönderene gideceğim” dedi."],["34","“Beni arayacaksınız, bulmayacaksınız. Benim olduğum yere siz gelemezsiniz.”"],["35","Bunun üzerine Yahudiler kendi aralarında, “Bu adam nereye gidecek de O’nu bulamayacağız?” dediler. “Grekler arasına dağılmış olanlara mı gidip Greklere mi öğretecek?"],["36","‘Beni arayacaksınız, bulmayacaksınız’ ve ‘olduğum yere siz gelemezsiniz’ dediği bu söz nedir?”"],["37","Bayramın son ve en büyük gününde, Yeşua ayağa kalkıp yüksek sesle, “Eğer bir kimse susadıysa, bana gelsin ve içsin!"],["38","Kutsal Yazı’nın dediği gibi, bana iman edenin içinden diri su ırmakları akacaktır” dedi."],["39","Bunu, kendisine iman edenlerin alacağı Ruh’la ilgili olarak söylüyordu. Çünkü Kutsal Ruh henüz verilmemişti. Çünkü Yeşua henüz yüceltilmemişti."],["40","Bunun üzerine kalabalığın çoğu bu sözleri duyunca, “Gerçekten bu o peygamberdir” dedi."],["41","Başkaları, “Bu Mesih’tir” diyordu. Ama bazıları, “Ne! Mesih Galile’den mi çıkacak?” dediler."],["42","“Kutsal Yazı, Mesih’in David’in soyundan, David’in köyü Beytlehem’den gelecek demedi mi?”"],["43","Böylece Yeşua’nın yüzünden halk arasında ayrılık doğdu."],["44","Bazıları O’nu yakalamak istediler, ama kimse O’na el sürmedi."],["45","Bunun üzerine, görevliler geri gelince, başkâhinlerle Ferisiler onlara, “O’nu neden getirmediniz?” dediler."],["46","Görevliler, “Hiç kimse bu adam gibi konuşmamıştır!” diye karşılık verdiler."],["47","Bunun üzerine Ferisiler onlara, “Siz de mi yoldan saptınız?"],["48","Önderlerden ya da Ferisiler’den O’na iman eden oldu mu hiç?"],["49","Yasa’yı bilmeyen bu kalabalık lanetlidir” diye karşılık verdiler."],["50","Onlardan biri olup geceleyin ve Yeşua’ya gelmiş olan Nikodim onlara,"],["51","“Yasamız, önce kendisini dinleyip ne yaptığını bilmedikçe, bir kişiyi yargılar mı?” dedi."],["52","Ona, “Sen de mi Galilelisin? Araştır bak, Galile’den hiç peygamber çıkmaz” diye karşılık verdiler."],["53","Herkes kendi evine gitti."]],8:[["1","Yeşua, Zeytin Dağı’na gitti."],["2","Sabah çok erkenden yine tapınağa geldi. Bütün halk O’na geliyordu. Oturup onlara öğretti."],["3","Yazıcılar ve Ferisiler zinada tutulmuş bir kadını getirdiler."],["4","Kadını orta yere dikip, “Öğretmen, bu kadını tam zina ederken bulduk” dediler."],["5","“Yasa’da Moşe bize böyle kadınların taşlanmasını buyurmuştur. Bu kadın hakkında sen ne diyorsun?”"],["6","Bunu, Yeşua’yı suçlu çıkarabilmek için, O’nu denemek amacıyla söylediler. Ama Yeşua yere eğilmiş parmağıyla yere yazı yazıyordu."],["7","Ama onlar kendisine sormayı sürdürmeleri üzerine doğrulup onlara, “İçinizde günahsız olan, ilk taşı ona atsın” dedi."],["8","Yine eğildi ve parmağıyla yere yazı yazdı."],["9","Bunu duydukları zaman, vicdanları tarafından mahkûm edilmiş olarak, en yaşlısından başlayarak en sonuncusuna kadar birer birer dışarı çıktılar. Yeşua'yı yalnız bıraktılar, kadın da bulunduğu yerde, ortadaydı."],["10","Yeşua doğrulunca kadını gördü ve ona “Kadın, seni suçlayanlar nerede? Kimse seni yargılamadı mı?” dedi."],["11","O, “Hiç kimse, Efendimiz” dedi. Yeşua, “Ben de seni yargılamıyorum. Yoluna git. Bundan böyle, artık günah işleme!” dedi."],["12","Bundan sonra Yeşua yine onlara şöyle dedi: “Ben dünyanın ışığıyım. Benim ardımdan gelen karanlıkta yürümez, hayat ışığına sahip olur.”"],["13","Bunun üzerine Ferisiler O’na, “Sen kendin hakkında tanıklık ediyorsun. Tanıklığın geçerli değil” dediler."],["14","Yeşua onlara şu karşılığı verdi: “Kendim hakkında tanıklık etsem bile, tanıklığım doğrudur. Çünkü nereden geldiğimi ve nereye gittiğimi biliyorum. Ama siz nereden geldiğimi, nereye gittiğimi bilmiyorsunuz."],["15","Siz bedene göre yargıda bulunuyorsunuz. Ben kimseyi yargılamam."],["16","Yargılasam bile benim yargım doğrudur; çünkü yalnız değilim, beni gönderen Baba ile birlikteyim."],["17","Yasanızda da iki kişinin tanıklığının geçerli olduğu yazılıdır."],["18","Bir ben kendim için tanıklık ediyorum, beni gönderen Baba da benim için tanıklık ediyor.”"],["19","Bunun üzerine O’na, “Baban nerede?” dediler. Yeşua onlara, “Siz ne beni ne de Babam’ı bilirsiniz. Eğer beni bilseydiniz, Babam’ı da bilirdiniz” dedi."],["20","Yeşua bu sözleri tapınakta öğretirken, hazinede söyledi. Yine de kimse O’nu tutuklamadı. Çünkü saati henüz gelmemişti."],["21","Bundan sonra Yeşua yine onlara, “Ben gidiyorum, beni arayacaksınız ve günahlarınız içinde öleceksiniz. Benim gittiğim yere siz gelemezsiniz” dedi."],["22","Bunun üzerine Yahudiler, “‘Benim gittiğim yere siz gelemezsiniz’ diyor. Yoksa kendini mi öldürecek?” dediler."],["23","Yeşua onlara, “Siz aşağıdansınız, ben yukarıdanım. Siz bu dünyadansınız, ben bu dünyadan değilim."],["24","Bu nedenle size günahlarınız içinde öleceksiniz dedim. Çünkü benim O olduğuma iman etmezseniz, günahlarınızın içinde öleceksiniz” dedi."],["25","Bunun üzerine O’na, “Sen kimsin?” dediler. Yeşua onlara, “Başlangıçtan beri size söylüyorum."],["26","Sizinle ilgili söyleyecek ve yargılayacak çok şeyim var. Ancak beni gönderen gerçektir ve ben O’ndan duyduklarımı dünyaya söylüyorum” dedi."],["27","Onlara Baba’dan söz ettiğini anlamadılar."],["28","Bu nedenle Yeşua onlara, “İnsanoğlu’nu yukarı kaldırdığınız zaman, benim O olduğumu, kendiliğimden hiçbir şey yapmadığımı, ancak Babam’ın bana öğrettiği gibi bu şeyleri söylediğimi bileceksiniz."],["29","Beni gönderen benimledir. Baba beni yalnız bırakmadı, çünkü ben her zaman O’nu hoşnut eden şeyleri yapıyorum” dedi."],["30","Yeşua bu şeyleri söylerken birçokları O’na iman etti."],["31","Yeşua, kendisine iman etmiş olan Yahudiler’e şöyle dedi: “Eğer benim sözümde kalırsanız, gerçekten benim öğrencilerim olursunuz."],["32","Gerçeği bileceksiniz ve gerçek sizi özgür kılacaktır.”"],["33","O’na, “Biz Avraham’ın soyundanız ve hiçbir zaman kimseye kölelik etmedik” diye karşılık verdiler. Nasıl olur da sen bize, ‘Özgür kılınacaksınız’ diyorsun?”"],["34","Yeşua onlara şu karşılığı verdi: “Size doğrusunu söyleyeyim, günah işleyen herkes günahın kölesidir."],["35","Hizmetçi daima evde yaşamaz. Ama oğul daima durur."],["36","Bu nedenle Oğul sizi özgür kılarsa, gerçekten özgür olursunuz."],["37","Avraham’ın soyundan olduğunuzu biliyorum. Buna karşın beni öldürmeye çalışıyorsunuz. Çünkü benim sözüm sizde yer bulmuyor."],["38","Ben Babam’la gördüğüm şeyleri söylüyorum, siz de babanızla gördüklerinizi yapıyorsunuz.”"],["39","O’na, “Bizim babamız Avraham’dır” diye yanıt verdiler. Yeşua onlara, “Eğer Avraham'ın çocukları olsaydınız, Avraham’ın işlerini yapardınız."],["40","Ama şimdi beni, Tanrı’dan duyduğum gerçeği size bildiren adamı öldürmeye çalışıyorsunuz. Avraham bunu yapmadı."],["41","Siz babanızın işlerini yapıyorsunuz” dedi. O’na “Biz zinadan doğmadık. Bizim bir Babamız var, O da Tanrı'dır” dediler."],["42","Bunun üzerine Yeşua onlara, “Tanrı Babanız olsaydı, beni severdiniz, çünkü ben Tanrı’dan çıkıp geldim. Çünkü kendiliğimden gelmedim, ama beni O gönderdi."],["43","Söylediğimi neden anlamıyorsunuz? Çünkü sözümü dinleyemiyorsunuz."],["44","Siz babanız İblis’tensiniz ve babanızın isteklerini yapmak istiyorsunuz. O başlangıçtan beri katildi. Gerçekte durmadı, çünkü onda gerçek yoktur. Yalan söylediğinde kendininkinden söyler. Çünkü o yalancıdır ve yalanların babasıdır."],["45","Ama ben gerçeği söylediğim için bana inanmıyorsunuz."],["46","Hangi biriniz beni günahla suçluyor? Eğer gerçeği söylüyorsam, neden bana iman etmiyorsunuz?"],["47","Tanrı’dan olan, Tanrı’nın sözlerini duyar. Bunun için siz duymuyorsunuz, çünkü siz Tanrı’dan değilsiniz” dedi."],["48","Bunun üzerine Yahudiler O’na, “Sen bir Samariyalı’sın ve sende iblis var demekle iyi dememiş miyiz?” dediler."],["49","Yeşua, “Bende iblis yok” dedi. “Ancak ben Babam’ı onurlandırıyorum ve siz beni aşağılıyorsunuz."],["50","Ben kendi yüceliğimi aramıyorum, ama bunu arayan ve yargılayan biri var."],["51","Size doğrusunu söyleyeyim, bir kimse sözümü tutarsa, ölümü asla görmeyecektir.”"],["52","O zaman Yahudiler O’na, “Şimdi sende iblis olduğunu biliyoruz” dediler. “Avraham da öldü, peygamberler de öyle ve sen diyorsun ki, ‘Bir kişi sözümü tutarsa, ölümü asla tatmayacak’."],["53","Yoksa sen, ölmüş olan babamız Avraham’dan daha mı büyüksün? Peygamberler öldü. Sen kendini kim sayıyorsun?”"],["54","Yeşua şöyle yanıt verdi: “Eğer ben kendimi yüceltirsem, yüceliğim bir hiçtir. Beni yücelten, ‘Tanrımız’ dediğiniz Babam’dır."],["55","Siz O’nu bilmiyorsunuz, ama ben O'nu biliyorum. ‘O’nu bilmiyorum’ dersem sizin gibi yalancı olurum. Ama O’nu biliyor ve sözünü tutuyorum."],["56","Babanız Avraham benim günümü göreceği için sevinmişti. Gördü ve sevindi.”"],["57","Bunun üzerine Yahudiler, “Sen henüz elli yaşında bile değilsin! Avraham’ı da mı gördün?” dediler."],["58","Yeşua onlara, “Size doğrusunu söyleyeyim, Avraham var olmadan önce ‘BEN VARIM ’” dedi."],["59","Bunun üzerine O’nu taşlamak için yerden taş aldılar. Yeşua kendini gizledi; ortalarından gelip geçerek tapınaktan çıktı."]],9:[["1","Yeşua geçerken doğuştan kör bir adam gördü."],["2","Öğrencileri O’na, “Rabbuni, kim günah işledi de bu adam kör doğdu? Kendisi mi, yoksa annesi babası mı?” diye sordular."],["3","Yeşua, “Ne o günah işledi, ne de anne babası” diye yanıtladı. “Tanrı’nın işleri onda açığa çıksın diye oldu."],["4","Beni gönderenin işlerini gündüzken yapmalıyım. Kimsenin çalışamayacağı, gece geliyor."],["5","Ben dünyada oldukça, dünyanın Işığı’yım.”"],["6","Bunu söyledikten sonra yere tükürdü, tükürükle çamur yaptı ve körün gözlerine sürdü."],["7","Ona, “Git, Şiloah Havuzu’nda yıkan” dedi. Şiloah gönderilmiş anlamına gelir. Böylece adam gidip yıkandı ve gözleri açılmış olarak geri döndü."],["8","Bunun üzerine komşuları ve onun daha önceden kör olduğunu görenler, “Oturup dilenen adam bu değil mi?” dediler."],["9","Bazıları, “Bu odur” diyordu. Bazıları da, “Hayır ona benziyor” diyordu. Adam, “Ben oyum” dedi."],["10","Bu nedenle ona, “Gözlerin nasıl açıldı?” diye sordular."],["11","O, “Yeşua adında bir adam çamur yapıp gözlerime sürdü ve bana, ‘Şiloah Havuzu’na gidip yıkan’ dedi. Ben de gidip yıkandım ve gözlerim açıldı” dedi."],["12","Sonra ona, “Nerede O?” diye sordular. “Bilmiyorum” dedi."],["13","Önceden kör olan adamı Ferisiler’e getirdiler."],["14","Yeşua’nın çamur yapıp gözlerini açtığı gün Şabat'dı."],["15","Bu nedenle Ferisiler de ona gözlerinin nasıl açıldığını yine sordular. Onlara, “Yeşua gözlerime çamur sürdü, yıkadım ve görüyorum” dedi."],["16","Bu nedenle Ferisiler’den bazıları, “Bu adam Tanrı’dan değil, çünkü Şabat'ı tutmuyor” dediler. Diğerleri, “Günahkâr bir adam nasıl böyle belirtiler yapabilir?” dediler. Bu nedenle aralarında ayrılık oldu."],["17","Bu yüzden köre tekrar sordular: “Gözlerini açan bu adam için sen ne diyorsun?” “O bir peygamberdir” dedi."],["18","Bu nedenle Yahudi yetkililer, ta ki gözleri açılan adamın annesiyle babasını çağırana dek, onun önceden kör olduğuna ve gözlerinin açıldığına inanmadılar."],["19","Onlara, “Kör doğdu dediğiniz oğlunuz bu mu? O halde şimdi nasıl görüyor?” diye sordular."],["20","Annesiyle babası onlara, “Bunun bizim oğlumuz olduğunu ve doğuştan kör olduğunu biliyoruz."],["21","Ama şimdi nasıl gördüğünü ve gözlerini kimin açtığını bilmiyoruz. Kendisi yaşını almıştır, ona sorun. Kendisi için konuşsun” diye karşılık verdiler."],["22","Annesiyle babası Yahudiler'den korktukları için bu şeyleri söylediler. Çünkü Yahudiler, her kim Yeşua’nın Mesih olduğunu açıkça söylerse, havra dışı edilecek diye anlaşmışlardı."],["23","Bu nedenle adamın anne babası, “Yaşını almıştır, kendisine sorun” demişlerdi."],["24","Böylece önceden kör olan adamı ikinci kez çağırıp, “Tanrı'yı yücelt. Bu adamın bir günahkâr olduğunu biz biliyoruz” dediler."],["25","Bunun üzerine adam, “Günahkâr olup olmadığını bilmiyorum. Bildiğim bir şey var, kördüm, şimdi görüyorum” dedi."],["26","Ona yine, “Sana ne yaptı? Gözlerini nasıl açtı?” dediler."],["27","Onlara şu karşılığı verdi: “Size zaten söyledim, ama dinlemiyorsunuz. Neden tekrar duymak istiyorsunuz? Siz de mi O’nun öğrencisi olmak istiyorsunuz?”"],["28","Onu aşağılayarak, “Sen O’nun öğrencisisin, biz Moşe’nin öğrencileriyiz” dediler."],["29","“Tanrı’nın Moşe ile konuştuğunu biliyoruz. Ama bu adama gelince, O’nun nereden geldiğini bilmiyoruz.”"],["30","Adam onlara, “Ne kadar hayret verici! Nereden geldiğini bilmiyorsunuz ama gözlerimi O açtı."],["31","Tanrı’nın günahkârları dinlemediğini biliyoruz. Tanrı kendisine tapan ve isteğini yerine getiren insanı dinler."],["32","Dünya var olduğundan beri, bir kimsenin doğuştan kör olan birinin gözlerini açtığı hiç duyulmamıştır."],["33","Bu adam Tanrı’dan olmasaydı, hiçbir şey yapamazdı” dedi."],["34","Ona, “Tamamen günah içinde doğmuş birisin, sen mi bize öğreteceksin?” diye karşılık verdiler. Sonra onu dışarı attılar."],["35","Yeşua, adamı dışarı attıklarını duydu. Onu bulup, “Tanrı’nın Oğlu’na iman ediyor musun?” diye sordu."],["36","Adam, “Ey Efendimiz, O kimdir ki, kendisine iman edeyim” diye yanıtladı."],["37","Yeşua ona, “Hem O’nu gördün, hem de seninle konuşan O’dur” dedi."],["38","“Efendimiz, iman ediyorum!” dedi. Ve Yeşua’ya tapındı."],["39","Yeşua, “Görmeyenler görsün, görenler kör olsun diye yargıçlık etmek üzere bu dünyaya geldim” dedi."],["40","Yanında duran Ferisiler'den olanlar bunu duyunca, “Yoksa biz de mi körüz?” dediler."],["41","Yeşua onlara, “Eğer kör olsaydınız, günahınız olmazdı; ama şimdi ‘Görüyoruz’ dediğiniz için günahınız yerinde duruyor” dedi."]],10:[["1","“Size doğrusunu söyleyeyim, koyun ağılına kapıdan girmeyip de başka yoldan tırmanan kişi hırsız ve hayduttur."],["2","Ama kapıdan giren koyunların çobanıdır."],["3","Kapıyı bekleyen ona kapıyı açar ve koyunlar onun sesini dinler. Kendi koyunlarını adıyla çağırır ve onları dışarı çıkarır."],["4","Kendi koyunlarını dışarı çıkardığında önlerinden gider ve koyunları onu izler. Çünkü onun sesini bilirler."],["5","Hiçbir şekilde bir yabancının ardından gitmezler, ondan kaçarlar. Çünkü yabancıların sesini tanımazlar.”"],["6","Yeşua bu benzetmeyi onlara söyledi, ama onlar O’nun kendilerine ne söylediğini anlamadılar."],["7","Bunun üzerine Yeşua yine onlara, “Size doğrusunu söyleyeyim” dedi. “Ben koyunların kapısıyım."],["8","Benden önce gelenlerin hepsi hırsız ve hayduttu, ama koyunlar onları dinlemedi."],["9","Ben kapıyım. Eğer bir kişi benim aracılığımla girerse kurtulur. Girer, çıkar ve otlak bulur."],["10","Hırsız yalnızca çalıp, öldürmek ve yok etmek için gelir. Ben insanlar hayata, doluca hayata sahip olsunlar diye geldim."],["11","Ben iyi çobanım. İyi çoban koyunları için hayatını verir."],["12","Koyunların çobanı ve sahibi olmayan ücretli adam, kurdun geldiğini görünce, koyunları bırakıp kaçar. Kurt, koyunları kapar ve onları dağıtır."],["13","Ücretli adam kaçar, çünkü ücretlidir ve koyunları umursamaz."],["14","Ben iyi çobanım. Benimkileri bilirim, benimkiler de beni bilir."],["15","Baba’nın beni bildiği, benim de Baba’yı bildiğim gibi. Koyunlarım için hayatımı veririm."],["16","Bu ağıldan olmayan başka koyunlarım var. Onları da getirmeliyim. Sesimi işitecekler, böylece tek çobanla tek sürü olacaklar."],["17","Hayatımı, yeniden geri almak üzere veririm. Bunun için Baba beni sever."],["18","Onu kimse benden almaz, ama onu ben kendim veririm. Onu vermeye de yeniden geri almaya da gücüm var. Bu buyruğu Babam’dan aldım.”"],["19","Bunun üzerine, bu sözlerden dolayı Yahudiler arasında yine ayrılık doğdu."],["20","Birçoğu, “O'nda iblis var, delidir” dedi. “Neden O’nu dinliyorsunuz?”"],["21","Başkaları ise, “Bunlar iblise tutulmuş bir adamın sözleri değil” dedi. “İblis, körlerin gözlerini açabilir mi hiç?”"],["22","Yeruşalem’de Adama Bayramı'ydı."],["23","Mevsim kıştı. Yeşua tapınakta Solomon’un Eyvanı’nda yürüyordu."],["24","Bunun üzerine Yahudiler O’nun çevresini sardılar ve O’na, “Bizi daha ne kadar kuşku içinde bırakacaksın? Eğer Mesih isen, bize açıkça söyle” dediler."],["25","Yeşua onlara şu karşılığı verdi: “Size söyledim, ama inanmıyorsunuz. Babam’ın adıyla yaptığım işler benim hakkımda tanıklık ediyor."],["26","Ama siz iman etmiyorsunuz. Çünkü size söylediğim gibi benim koyunlarımdan değilsiniz."],["27","Koyunlarım sesimi işitir, ben onları bilirim, onlar da ardımdan gelir."],["28","Onlara sonsuz hayat veririm. Asla mahvolmayacaklar ve hiç kimse onları elimden kapamaz."],["29","Onları bana veren Babam her şeyden büyüktür. Onları Babam’ın elinden kapmaya kimsenin gücü yetmez."],["30","Ben ve Baba biriz.”"],["31","Bunun üzerine Yahudiler O’nu taşlamak için yine yerden taş kaldırdılar."],["32","Yeşua onlara şu karşılığı verdi: “Size Babam’dan birçok iyi işler gösterdim. Bu işlerden hangisi için beni taşlıyorsunuz?”"],["33","Yahudiler O’na, “Seni iyi işlerden dolayı değil, ettiğin küfür için taşlıyoruz. Çünkü insanken kendini Tanrı yaptın” dediler."],["34","Yeşua onlara şöyle karşılık verdi: “‘Siz ilâhlarsınız dedim’ diye yasanızda yazılı değil mi?"],["35","Eğer O, kendilerine Tanrı'nın sözü gelenlere, ilâhlar dediyse ve Kutsal Yazı bozulamaz,"],["36","‘Ben Tanrı’nın Oğlu’yum’ dediğim için, Baba'nın ayırıp dünyaya gönderdiği kişiye mi, ‘Küfrediyorsun’ diyorsunuz?"],["37","Eğer Babam’ın işlerini yapmıyorsam, bana iman etmeyin."],["38","Yok eğer yapıyorsam, bana iman etmeseniz bile, yapılan işlere inanın. Öyle ki Baba’nın bende, benim de Baba’da olduğumu bilip iman edesiniz.”"],["39","O’nu yine yakalamaya çalıştılar. Ama Yeşua onların elinden çıkıp gitti."],["40","Yine Yarden'in ötesine, Yuhanna’nın başlangıçta vaftiz ettiği yere gitti ve orada kaldı."],["41","Birçokları O’na geldi. “Gerçi Yuhanna hiç belirti yapmadı. Ama Yuhanna’nın bu adam hakkında söylediği her şey doğru” diyorlardı."],["42","Orada birçokları O’na iman etti."]],11:[["1","Mariyam ve kız kardeşi Marta’nın köyü olan Beytanya’dan Lazar adında bir adam hastaydı."],["2","Hasta olan Lazar, Efendi’ye güzel kokulu yağ sürüp saçlarıyla ayaklarını silen Mariyam’ın kardeşiydi."],["3","Bunun üzerine kız kardeşler, “Efendimiz, çok sevdiğin kişi hasta” diyerek Yeşua’ya haber gönderdiler."],["4","Yeşua bunu duyunca, “Bu hastalık ölüm için değil; Tanrı Oğlu bununla yücelsin diye, Tanrı'nın yüceliği içindir.” dedi."],["5","Yeşua Marta’yı, kız kardeşini ve Lazar’ı severdi."],["6","Öyleyken hasta olduğunu duyunca bulunduğu yerde iki gün daha kaldı."],["7","Bundan sonra öğrencilerine, “Yine Yahudiye’ye gidelim” dedi."],["8","Öğrencileri O’na, “Rabbuni, Yahudiler seni taşlamaya kalkıştılar. Yine mi oraya gidiyorsun?” diye sordular."],["9","Yeşua onlara, “Gün ışığının on iki saati yok mu? Gündüz yürüyen sendelemez. Çünkü bu dünyanın ışığını görür."],["10","Ama gece yürüyen sendeler. Çünkü kendisinde ışık yoktur.”"],["11","Bunları söyledikten sonra onlara şöyle dedi, “Dostumuz Lazar uyudu, ama ben onu uykudan uyandırmaya gidiyorum.”"],["12","Bunun üzerine öğrenciler, “Efendimiz, uyuyorsa iyileşecektir” dediler."],["13","Yeşua onun ölümünden söz etmişti. Ama onlar uykuda dinlendiğinden söz ettiğini sandılar."],["14","O zaman Yeşua onlara açıkça, “Lazar öldü” dedi."],["15","“İman edesiniz diye orada bulunmadığıma sizin adınıza seviniyorum. Yine de, şimdi ona gidelim.”"],["16","Bunun üzerine Didimos diye anılan Tomas diğer öğrencilere, “Biz de gidelim, onunla birlikte ölelim” dedi."],["17","Böylece Yeşua geldiğinde, Lazar’ın dört gündür mezarda yatmakta buldu."],["18","Beytanya Yeruşalem yakınlarında, yaklaşık on beş stadia uzaklıktaydı."],["19","Yahudiler’den birçoğu, erkek kardeşleri için Marta ile Mariyam’ı avutmaya gelmişti."],["20","O zaman Marta Yeşua’nın geldiğini duyunca O’nu karşılamaya çıktı, ama Mariyam evde kaldı."],["21","Marta Yeşua’ya, “Efendimiz, sen burada olsaydın, kardeşim ölmezdi” dedi."],["22","“Şimdi bile, Tanrı’dan ne dilersen, Tanrı’nın sana vereceğini biliyorum.”"],["23","Yeşua ona, “Kardeşin dirilecek” dedi."],["24","Marta O’na, “Son gün, dirilişte onun yeniden dirileceğini biliyorum” dedi."],["25","Yeşua ona, “Diriliş ve hayat Ben’im” dedi. “Bana iman eden kişi ölse bile yaşayacaktır."],["26","Yaşayan ve bana iman eden asla ölmeyecek. Buna iman ediyor musun?”"],["27","Marta O'na, “Evet, Efendimiz” dedi. “Senin, dünyaya gelecek olan Tanrı’nın Oğlu Mesih olduğuna iman ettim.”"],["28","Bunu söyledikten sonra gidip kız kardeşi Mariyam’ı gizlice çağırdı. “Öğretmen burada, seni çağırıyor” dedi."],["29","Mariyam bunu duyunca hemen kalkıp Yeşua’nın yanına gitti."],["30","Yeşua henüz köye gelmemişti, hâlâ Marta’nın O’nu karşıladığı yerdeydi."],["31","Mariyam’la birlikte evde bulunan ve onu avutan Yahudiler, Mariyam’ın hızlıca kalkıp dışarı çıktığını görünce, “Orada ağlamak için mezara gidiyor” diyerek onun peşinden gittiler."],["32","Mariyam, Yeşua’nın bulunduğu yere gelince O'nu gördü ve ayaklarına kapanıp O'na, “Efendimiz, burada olsaydın, kardeşim ölmezdi” dedi."],["33","Yeşua, Mariyam’ın ve onunla gelen Yahudiler’in ağladığını görünce, ruhunda inledi ve sıkıntı çekti."],["34","“Onu nereye yatırdınız?” dedi. O’na, “Efendimiz, gel de gör” dediler."],["35","Yeşua ağladı."],["36","Bunun üzerine Yahudiler, “Bakın, onu ne kadar seviyormuş!” dediler."],["37","Bazıları, “Körün gözlerini açan bu adam, Lazar’ın ölmesine de engel olamaz mıydı?” dediler."],["38","Bunun üzerine Yeşua yine içinden inleyerek mezara geldi. Mezar bir mağaraydı ve önünde bir taş duruyordu."],["39","Yeşua, “Taşı kaldırın” dedi. Ölmüş olanın kız kardeşi Marta, “Efendimiz, bu zamana dek artık kokmuştur, öleli dört gün oldu” dedi."],["40","Yeşua ona, “Eğer iman edersen Tanrı’nın yüceliğini göreceğini sana söylemedim mi?” dedi."],["41","Böylece ölünün yattığı yerden taşı kaldırdılar. Yeşua gözlerini kaldırıp, “Baba, beni dinlediğin için sana şükrediyorum."],["42","Beni her zaman dinlediğini biliyorum. Ama bunu etrafımda duran kalabalık için, beni senin gönderdiğine iman etsinler diye söyledim” dedi."],["43","Bunu söyledikten sonra yüksek sesle, “Lazar, dışarı gel!” diye bağırdı."],["44","Ölmüş olan dışarı çıktı. Eli ve ayağı sargılarla bağlı ve yüzü bir bezle sarılıydı. Yeşua onlara, “Onu çözün, bırakın gitsin” dedi."],["45","Bunun üzerine, Mariyam’a gelip Yeşua’nın yaptıklarını gören Yahudiler’den birçoğu O’na iman etti."],["46","Ama onlardan bazıları Ferisiler’e gidip Yeşua’nın yaptıklarını onlara anlattı."],["47","Bunun üzerine başkâhinler ve Ferisiler Yüksek Kurul’u toplayıp, “Ne yapacağız? Bu adam birçok belirti gerçekleştiriyor” dediler."],["48","“O’nu böylece bırakırsak, herkes O’na iman edecek. Romalılar da gelip hem yerimizi hem de ulusumuzu kaldıracaklar.”"],["49","Ama içlerinden biri, o yıl başkâhin olan Kayafa, “Hiçbir şey bilmiyorsunuz” dedi."],["50","“Bütün ulus yok olmasın diye halk için bir adamın ölmesi bizim yararımıza olduğunu görmüyor musunuz?”"],["51","Bunu kendiliğinden söylememişti. O yılın başkâhini olarak, Yeşua’nın ulus için,"],["52","Yalnızca ulus için değil, Tanrı’nın dağılmış çocuklarını bir araya toplamak için de öleceğini peygamberlik etti."],["53","O günden itibaren O’nu öldürmek için öğütleştiler."],["54","Bu nedenle Yeşua artık Yahudiler arasında açıktan dolaşamaz oldu. Oradan çöle yakın bir yere, Efraim adlı kente gitti. Öğrencileriyle birlikte orada kaldı."],["55","Yahudiler’in Pesah'ı yakındı. Taşradan birçok kişi kendilerini arındırmak üzere Pesah'dan önce Yeruşalem’e çıktılar."],["56","Sonra Yeşua’yı aradılar, tapınaktayken birbirlerine, “Ne dersiniz, bayrama hiç gelmeyecek mi?” diye konuşuyorlardı."],["57","Başkâhinler ve Ferisiler, O’nun nerede olduğunu bilen varsa haber versin diye buyurmuşlardı. Öyle ki, O’nu yakalayabilsinler."]],12:[["1","O zaman Pesah'tan altı gün önce Yeşua, ölümden dirilttiği Lazar’ın bulunduğu Beytanya’ya geldi."],["2","Böylece orada O'na bir ziyafet verdiler. Marta hizmet ediyordu. Lazar da Yeşua’yla birlikte masada oturanlardan biriydi."],["3","Bunun üzerine Mariyam, çok değerli saf hintsümbülü yağından bir litre alıp Yeşua’nın ayaklarına sürdü ve saçlarıyla ayaklarını sildi. Ev yağın güzel kokusuyla doldu."],["4","O zaman öğrencilerinden biri, Yeşua’ya ihanet edecek olan Simon’un oğlu Yahuda İskariot,"],["5","“Bu yağ neden üç yüz dinara satılıp yoksullara verilmedi?” dedi."],["6","Bunu, yoksullarla ilgilendiği için değil, hırsız olduğu için söylüyordu. Para kutusu ondaydı ve içine konulandan çalıyordu."],["7","Yeşua, “Kadını rahat bırak. Bunu gömüleceğim gün için sakladı."],["8","Çünkü yoksullar her zaman sizinle birliktedir, ama ben her zaman sizinle birlikte değilim.”"],["9","Yahudiler’den büyük bir kalabalık Yeşua’nın orada olduğunu öğrendi ve yalnızca Yeşua için değil, ölümden dirilttiği Lazar’ı da görmek için geldiler."],["10","Başkâhinler Lazar’ı da öldürmek için bir düzen kurdular."],["11","Çünkü onun yüzünden birçok Yahudi gidip Yeşua’ya iman ediyordu."],["12","Ertesi gün, büyük bir kalabalık bayrama geldi. Yeşua’nın Yeruşalem’e gelmekte olduğunu duyduklarında,"],["13","Palmiye dallarını alıp O’nu karşılamaya çıktılar. “Hozana! Efendi’nin adıyla gelene, İsrael Kralı’na övgüler olsun!” diye bağırıyorlardı."],["14","Yeşua bir sıpa bulup üzerine bindi."],["15","Yazılmış olduğu gibi, “Korkma, Siyon kızı! İşte, Kralın sıpaya binmiş geliyor.”"],["16","Öğrencileri ilk başta bu şeyleri anlamadılar. Ama Yeşua yüceltildikten sonra bu şeylerin O’nun hakkında yazıldığını ve onların bu şeyleri O’nun için yaptığını hatırladılar."],["17","Lazar’ı mezardan çağırıp ölümden dirilttiğinde yanında bulunan kalabalık buna tanıklık etti."],["18","Bu nedenle Yeşua’nın yapmış olduğu bu belirtiyi duyan kalabalık da O’nu karşılamaya çıktı."],["19","Bunun üzerine Ferisiler kendi aralarında, “Bakın, bir şey yapamıyorsunuz. İşte, dünya O’nun peşinden gitti” dediler."],["20","Bayramda tapınmak için çıkanlar arasında bazı Grekler de vardı."],["21","Bunlar, Galile’nin Beytsayda Kenti’nden olan Filipus’a gelip ona, “Efendimiz, Yeşua’yı görmek istiyoruz” dediler."],["22","Filipus gelip Andreas’a söyledi. Andreas’la Filipus gelip Yeşua’ya bildirdiler."],["23","Yeşua onlara şu karşılığı verdi: “İnsanoğlu’nun yüceltileceği zaman geldi."],["24","Size doğrusunu söyleyeyim, buğday tanesi toprağa düşüp ölmedikçe, tek başına yalnız kalır. Ama ölürse, bol ürün verir."],["25","Hayatını seven onu kaybedecek. Bu dünyada hayatından nefret eden onu sonsuz hayat için saklar."],["26","Eğer biri bana hizmet edecekse, ardımdan gelsin. Ben neredeysem, hizmetkârım da orada olacaktır. Eğer biri bana hizmet ederse, Baba onu onurlandıracaktır.”"],["27","“Şimdi canım sıkıntı çekiyor. Ne diyeyim? ‘Baba, kurtar beni bu zamandan’ mı diyeyim? Ama ben bu amaç için bu zamana geldim."],["28","Baba, adını yücelt!” O zaman gökyüzünden bir ses geldi: “Adımı hem yücelttim, hem de yücelteceğim.” dedi."],["29","Bunun üzerine, orada duran ve bunu duyan kalabalık, “Gök gürledi” dedi. Diğerleri, “O’nunla bir melek konuştu” dedi."],["30","Yeşua şöyle karşılık verdi, “Bu ses benim için değil, sizin için geldi”"],["31","“Bu dünyanın yargısı şimdidir. Şimdi bu dünyanın hükümdarı kovulacak."],["32","Ben yerden yukarı kaldırılırsam, bütün insanları kendime çekeceğim.”"],["33","Yeşua ne tür ölümle öleceğini işaret ederek, bunu söyledi."],["34","Kalabalık O’na şöyle yanıt verdi: “Kutsal Yasa’dan duyduk ki, Mesih sonsuza dek kalacaktır. Sen nasıl, ‘İnsanoğlu’nun yukarı kaldırılması gerekiyor’ diyorsun? Kimdir bu İnsanoğlu?”"],["35","Bunun üzerine Yeşua onlara, “Kısa bir süre daha ışık sizinle birliktedir” dedi. “Işığınız varken yürüyün ki, karanlık sizi yakalamasın. Karanlıkta yürüyen nereye gittiğini bilmez."],["36","Işığınız varken, ışığa iman edin. Öyle ki ışık çocukları olasınız.” Yeşua bunları söyledikten sonra oradan ayrılıp onlardan gizlendi."],["37","Önlerinde bunca belirti gerçekleştirmesine karşın O’na iman etmediler."],["38","Bunlar Peygamber Yeşaya’nın söylediği şu söz yerine gelsin diye oldu: “Efendimiz, verdiğimiz habere kim inandı? Efendi’nin kolu kime gösterildi?”"],["39","Bu nedenle iman edemiyorlardı. Yine Yeşaya şöyle demişti:"],["40","“Onların gözlerini kör etti, Yüreklerini katılaştırdı, gözleriyle görmesinler, ve yürekleriyle anlamasınlar, ve dönmesinler. Ben de onları iyileştirmeyeyim.”"],["41","Yeşaya, Yeşua’nın yüceliğini görmüş ve O’nun hakkında bu şeyleri söylemiştir."],["42","Yine de önderlerden birçoğu O’na iman etti. Ama Ferisiler’den korktuklarından, havra dışı edilmemek için bunu açıkça söylemediler."],["43","Çünkü insanın övgüsünü, Tanrı’nın övgüsünden çok sevdiler."],["44","Yeşua yüksek sesle, “Bana iman eden bana değil, beni gönderene iman eder” dedi."],["45","“Beni gören de, beni göndereni görür."],["46","Bana iman eden hiç kimse karanlıkta kalmasın diye dünyaya ışık olarak geldim."],["47","Sözlerimi işitip de inanmayanı ben yargılamam. Çünkü ben dünyayı yargılamaya değil, kurtarmaya geldim."],["48","Beni reddedip sözlerimi kabul etmeyeni yargılayacak olan biri vardır. O kişiyi son günde yargılayacak olan söylediğim sözdür."],["49","Çünkü ben kendiliğimden konuşmadım. Beni gönderen Baba’nın kendisi ne söylemem ve ne konuşmam gerektiğini bana buyurdu."],["50","O’nun buyruğu sonsuz hayattır. Bunun için söylediğim şeyleri, Baba’nın bana bildirdiği gibi söylüyorum.”"]],13:[["1","Pesah Bayramı’ndan önceydi. Yeşua, bu dünyadan Baba’ya gitme vaktinin gelmiş olduğunu biliyordu. Dünyada kendisinin olanları sevmişti ve onları sonuna dek sevdi."],["2","Akşam yemeği sırasında, İblis, Simon oğlu Yahuda İskariot’un yüreğine Yeşua’yı ele vermeyi çoktan koymuştu."],["3","Yeşua, Baba’nın her şeyi kendi eline verdiğini, Tanrı’dan geldiğini ve Tanrı’ya gitmekte olduğunu biliyordu."],["4","Yemekten kalktı, giysisinin üstlüğünü bir kenara koydu, bir havlu alıp beline sardı."],["5","Sonra leğene su koyup öğrencilerin ayaklarını yıkamaya ve beline sardığı havluyla silmeye başladı."],["6","Ondan sonra Simon Petrus’a geldi. Simon, “Efendimiz, ayaklarımı sen mi yıkayacaksın?” dedi."],["7","Yeşua ona, “Şimdi ne yaptığımı bilmiyorsun, ama sonra anlayacaksın” diye yanıtladı."],["8","Petrus, “Benim ayaklarımı asla yıkamayacaksın!” dedi. Yeşua ona, “Eğer seni yıkamazsam, benimle bir payın olmaz” diye yanıtladı."],["9","Simon Petrus O’na, “Efendimiz, o zaman yalnız ayaklarımı değil, ama ellerimi ve başımı da yıka!” dedi."],["10","Yeşua ona, “Yıkanmış birinin yalnızca ayaklarının yıkanması gerekir, ama tamamen temizdir” dedi. “Siz temizsiniz, ama hepiniz değil.”"],["11","Kendisine ihanet edecek kişiyi bildiği için, “Hepiniz temiz değilsiniz” demişti."],["12","Böylece onların ayaklarını yıkadıktan sonra üstlüğünü giyip yine sofraya oturdu. Onlara, “Size ne yaptığımı biliyor musunuz?"],["13","Siz bana ‘Öğretmen’ ve ‘Efendi’ diyorsunuz. Doğru söylüyorsunuz, çünkü ben öyleyim."],["14","Eğer ben Efendi ve Öğretmen’ken ayaklarınızı yıkadığıma göre, siz de birbirinizin ayaklarını yıkamalısınız."],["15","Size yaptığım gibi, siz de yapasınız diye size bir örnek verdim."],["16","Size doğrusunu söyleyeyim, hizmetkâr efendisinden, gönderilen de kendisini gönderenden daha büyük değildir."],["17","Eğer bildiğiniz bu şeyleri yaparsanız, ne mutlu size!” dedi."],["18","“Hepiniz için söylemiyorum, ben kimleri seçtiğimi biliyorum. Ama Kutsal Yazı yerine gelmeliydi, ‘Benimle ekmek yiyen bana karşı alçaklığını kaldırdı.’"],["19","Bunları size gerçekleşmeden önce, şimdiden söylüyorum. Öyle ki, gerçekleştiğinde benim O olduğuma iman edesiniz."],["20","Size doğrusunu söyleyeyim, gönderdiğim kişiyi kabul eden, beni kabul eder. Beni kabul eden de beni göndereni kabul eder.”"],["21","Bunları söyledikten sonra Yeşua ruhunda sıkıntı duydu. Şöyle tanıklık etti: “Size doğrusunu söyleyeyim, biriniz bana ihanet edecek.”"],["22","Öğrenciler kimin hakkında konuştuğunu merak edip birbirlerine baktılar."],["23","Öğrencilerinden biri, Yeşua’nın sevdiği öğrenci, Yeşua’nın göğsüne yaslanmıştı."],["24","Simon Petrus, kimden söz ettiğini Yeşua’ya sorsun diye, ona işaret etti."],["25","O da Yeşua’nın göğsüne yaslanmış vaziyette, “Efendimiz, kimdir o?” diye sordu."],["26","Bunun üzerine Yeşua, “Bu lokmayı batırıp kendisine vereceğim kim ise, odur” dedi. Böylece lokmayı batırdıktan sonra, onu Simon İskariot’un oğlu Yahuda’ya verdi."],["27","Lokmadan sonra, o vakit Şeytan onun içine girdi. Sonra Yeşua ona, “Yapacağını çabuk yap” dedi."],["28","Sofrada oturanlardan hiç kimse Yeşua’nın ona bunu neden söylediğini anlamadı."],["29","Para kutusu Yahuda’da olduğundan bazıları Yeşua’nın ona, “Bayram için gerekli şeyleri satın al” ya da “Yoksullara bir şey ver’’ dediğini sandılar."],["30","Yahuda lokmayı alınca hemen dışarı çıktı. Geceydi."],["31","Yahuda dışarı çıkınca Yeşua, “Şimdi İnsanoğlu yüceltildi ve Tanrı O’nda yüceltildi” dedi."],["32","“Eğer Tanrı O’nda yüceltildiyse, Tanrı da O’nu kendinde yüceltecektir. Hem de O’nu hemen yüceltecektir."],["33","Çocuklar, bir süre daha sizinle olacağım. Beni arayacaksınız, Yahudiler’e, ‘Gideceğim yere gelemezsiniz’ dediğim gibi, şimdi size söylüyorum."],["34","Size yeni bir buyruk veriyorum: Birbirinizi sevin. Benim sizi sevdiğim gibi siz de birbirinizi sevin."],["35","Birbirinize sevginiz olursa, bununla herkes benim öğrencilerim olduğunuzu bilecektir.”"],["36","Simon Petrus O’na, “Efendimiz, nereye gidiyorsun?” diye sordu. Yeşua, “Gideceğim yere şimdi ardımdan gelemezsiniz, ama sonra ardımdan geleceksiniz” diye yanıtladı."],["37","Petrus O’na, “Efendimiz, neden şimdi senin ardından gelemeyeyim? Senin için hayatımı veririm!” dedi."],["38","Yeşua ona şöyle yanıt verdi, “Benim için hayatını mı vereceksin? Sana doğrusunu söyleyeyim, sen beni üç kez inkâr edene kadar, horoz ötmeyecektir.”"]],14:[["1","“Yüreğiniz sıkılmasın, Tanrı’ya iman edin. Bana da iman edin."],["2","Babam’ın evinde çok evler var. Öyle olmasaydı, size söylerdim. Size yer hazırlamaya gidiyorum."],["3","Gidip size yer hazırlarsam, siz de benim olduğum yerde olasınız diye yine gelip sizi kendi yanıma alacağım."],["4","Gittiğim yeri ve yolu biliyorsunuz.”"],["5","Tomas, “Efendimiz, nereye gittiğini bilmiyoruz” dedi. “Yolu nasıl bilebiliriz?”"],["6","Yeşua ona, “Yol, gerçek ve hayat Ben’im” dedi. “Benim aracılığım olmadan kimse Baba’ya gelemez."],["7","Eğer beni tanımış olsaydınız, Babam’ı da tanırdınız. Bundan böyle artık O’nu tanıyorsunuz ve O’nu gördünüz.”"],["8","Filipus O’na, “Efendimiz, bize Baba’yı göster, bu bize yeter” dedi."],["9","Yeşua ona, “Filipus bunca zamandır sizinle birlikteyim ve beni tanımadın mı?” dedi. “Beni görmüş olan, Baba’yı görmüştür. Sen nasıl ‘Bize Baba’yı göster’ diyorsun?"],["10","Benim Baba’da, Baba’nın bende olduğuna inanmıyor musun? Size söylediğim sözleri kendiliğimden söylemiyorum, ama bende yaşayan Baba kendi işlerini yapıyor."],["11","Bana iman edin; ben Baba’dayım, Baba da bendedir. Hiç olmazsa bu işlerden dolayı iman edin."],["12","Size doğrusunu söyleyeyim, benim yaptığım işleri bana iman eden de yapacaktır. Bunlardan daha büyüklerini de yapacaktır. Çünkü ben Babam’a gidiyorum."],["13","Baba Oğul’da yüceltilsin diye benim adımla her ne dilerseniz yapacağım."],["14","Benim adımla ne dilerseniz yapacağım."],["15","Beni seviyorsanız, buyruklarımı tutarsınız."],["16","Baba’ya dua edeceğim, O da daima sizinle birlikte olsun diye size başka bir Yardımcı, Gerçeğin Ruhu’nu verecek."],["17","O'nu, dünya kabul edemez, O'nu görmez ve O'nu bilmez. Siz O’nu biliyorsunuz. Çünkü sizinle yaşıyor ve içinizde olacaktır."],["18","Sizi yetim bırakmayacağım. Size geleceğim."],["19","Kısa bir süre sonra artık dünya beni görmeyecek ama siz beni göreceksiniz. Çünkü ben yaşıyorum, siz de yaşayacaksınız."],["20","O gün bileceksiniz ki, ben Babam’dayım, siz bendesiniz, ben de sizdeyim."],["21","Beni seven kişi, buyruklarım kendisinde olup onları tutandır. Beni seven, Babam tarafından sevilecektir. Ben de onu seveceğim ve kendimi ona göstereceğim.”"],["22","Yahuda (İskariot değil) O’na, “Efendimiz, ne oldu ki, kendini dünyaya değil, bize göstereceksin?” dedi."],["23","Yeşua ona şu karşılığı verdi: “Kim beni severse, sözümü tutar. Babam onu sever. Biz de ona gelir, onunla evimizi yaparız."],["24","Beni sevmeyen sözlerimi tutmaz. Duyduğunuz söz benim değil, beni gönderen Baba’nındır."],["25","Bu şeyleri size daha sizinle yaşarken söyledim."],["26","Ama Baba’nın benim adımla göndereceği Tesellici, Kutsal Ruh size her şeyi öğretecek ve söylediklerimin hepsini size hatırlatacak."],["27","Size esenlik bırakıyorum. Size kendi esenliğimi veriyorum. Ben size dünyanın verdiği gibi vermiyorum. Yüreğiniz sıkılmasın ve korkmasın."],["28","‘Gidiyorum ama yine size geleceğim’ dediğimi duydunuz. Eğer beni sevseydiniz, Baba’ya gideceğim için sevinirdiniz. Çünkü Baba benden büyüktür."],["29","Gerçekleşmeden önce bunu şimdi size söyledim. Öyle ki, bu gerçekleştiğinde iman edesiniz."],["30","Artık sizinle daha fazla konuşmayacağım. Çünkü dünyanın hükümdarı geliyor ve onun bende hiçbir şeyi yoktur."],["31","Ama dünya bilsin ki, ben Baba’yı severim ve Baba'nın bana buyurduğu gibi, öyle yaparım. Kalkın, buradan gidelim.”"]],15:[["1","“Ben gerçek asmayım ve Babam çiftçidir."],["2","Bende ürün vermeyen her çubuğu alıp götürür. Ürün veren her çubuğu ise daha çok ürün versin diye budar."],["3","Size söylediğim sözden dolayı siz zaten temizsiniz."],["4","Bende kalın, ben de sizde kalayım. Çubuk asmada kalmadıkça kendiliğinden ürün veremeyeceği gibi, siz de bende kalmazsanız ürün veremezsiniz."],["5","Ben asmayım, siz çubuklarsınız. Bende kalan ve benim kendisinde kaldığım kişi bol ürün verir. Çünkü bensiz hiçbir şey yapamazsınız."],["6","Bir kimse bende kalmazsa, çubuk gibi dışarı atılır ve kurur. Bunları toplayıp ateşe atarlar, onlar da yanar."],["7","Eğer bende kalırsanız ve sözlerim sizde kalırsa, ne isterseniz dileyin, sizin için yapılacaktır.”"],["8","“Babam, bol ürün vermenizle, bununla yüceltilir. Böylece öğrencilerim olursunuz."],["9","Baba’nın beni sevdiği gibi, ben de sizi sevdim. Sevgimde kalın."],["10","Buyruklarımı tutarsanız, sevgimde kalırsınız. Tıpkı benim de Baba’nın buyruklarını tutup O’nun sevgisinde kaldığım gibi."],["11","Bu şeyleri size, sevincim sizde kalsın ve sevinciniz tamamlansın diye söyledim.”"],["12","“Benim buyruğum şudur: Sizi sevdiğim gibi siz de birbirinizi sevin."],["13","Hiç kimsede, birinin dostları uğruna hayatını vermesinden daha büyük bir sevgi yoktur."],["14","Size buyurduklarımı yaparsanız, benim dostlarım olursunuz."],["15","Artık size hizmetkâr demiyorum, çünkü hizmetkâr efendisinin ne yaptığını bilmez. Ama ben size dostlar dedim, çünkü Babam’dan duyduğum her şeyi size bildirdim."],["16","Siz beni seçmediniz, ben sizi seçtim. Gidip ürün veresiniz ve ürününüz kalıcı olsun diye sizi ben atadım. Öyle ki, benim adımla Baba’dan ne dilerseniz, size versin.”"],["17","“Birbirinizi sevesiniz diye bu şeyleri size buyuruyorum."],["18","Eğer dünya sizden nefret ederse, sizden önce benden nefret etmiş olduğunu bilin."],["19","Eğer dünyadan olsaydınız, dünya kendinin olanı severdi. Çünkü dünyadan değilsiniz, ancak ben sizi dünyadan seçtim. Bu nedenle dünya sizden nefret ediyor."],["20","Size söylediğim sözü hatırlayın: ‘Hizmetkâr efendisinden büyük değildir.’ Eğer bana zulmettilerse, size de zulmedecekler. Eğer benim sözümü tuttularsa, sizinkini de tutacaklar."],["21","Ama bütün bu şeyleri benim adım uğruna size yapacaklar. Çünkü onlar beni göndereni tanımıyorlar."],["22","Gelmemiş ve onlarla konuşmamış olsaydım, günahları olmazdı. Ama şimdi günahları için hiçbir özürleri yoktur."],["23","Benden nefret eden, Babam’dan da nefret eder."],["24","Eğer başka hiç kimsenin yapmadığı işleri onların arasında yapmamış olsaydım, günahları olmazdı. Ama şimdi yaptıklarımı gördükleri halde hem benden hem de Babam’dan nefret ettiler."],["25","Bu, yasalarında yazılı, ‘Benden sebebsiz yere nefret ettiler’ sözü yerine gelsin diye oldu.”"],["26","“Baba’dan size göndereceğim Yardımcı, Baba’dan çıkan Gerçeğin Ruhu geldiği zaman, bana tanıklık edecek."],["27","Siz de tanıklık edeceksiniz, çünkü başlangıçtan beri benimle birliktesiniz.”"]],16:[["1","“Bu şeyleri size, tökezletilmeyesiniz diye söyledim."],["2","Sizi havra dışı edecekler. Evet, öyle bir zaman geliyor ki, her kim sizi öldürürse Tanrı’ya hizmet ettiğini sanacak."],["3","Bu şeyleri yapacaklar, çünkü ne Baba’yı ne de beni tanıyorlar."],["4","Ama bu şeyleri size söylüyorum. Öyle ki, zamanı gelince bunları size söylediğimi hatırlayasınız. Bu şeyleri size başlangıçta söylemedim çünkü sizinle birlikteydim."],["5","Ama şimdi beni gönderene gidiyorum ve hiçbiriniz bana, ‘Nereye gidiyorsun?’ diye sormuyor."],["6","Ama bu şeyleri size söylediğim için yüreğinizi keder doldurdu."],["7","Bununla birlikte size gerçeği söylüyorum, benim gitmem sizin yararınızadır. Çünkü ben gitmezsem Tesellici size gelmez. Ama gidersem, O’nu size gönderirim."],["8","O gelince günah hakkında, doğruluk hakkında ve yargı hakkında dünyayı ikna edecek."],["9","Günah hakkında, çünkü bana iman etmezler."],["10","Doğruluk hakkında, çünkü ben Babam’a gidiyorum ve artık beni görmeyeceksiniz."],["11","Yargı hakkında, çünkü bu dünyanın hükümdarı yargılandı.”"],["12","“Size anlatacak daha çok şeyim var, ama şimdi bunlara dayanamazsınız."],["13","Ancak O, Gerçeğin Ruhu gelince, sizi tüm gerçeğe yöneltecek. Çünkü kendiliğinden konuşmayacak, ama her ne duyarsa söyleyecek. Size gelecekte olacakları bildirecek."],["14","O beni yüceltecek, çünkü benim olandan alacak ve size bildirecek."],["15","Baba’nın sahip olduğu her şey benimdir. Bu nedenle benim olandan alacak ve size bildirecek dedim."],["16","Kısa bir süre sonra beni görmeyeceksiniz. Yine kısa bir süre sonra beni göreceksiniz.”"],["17","Bunun üzerine öğrencilerinden bazıları birbirlerine, “Bize, ‘Kısa bir süre sonra beni görmeyeceksiniz ve yine kısa bir süre sonra beni göreceksiniz’ diyerek söylediği bu nedir?” dediler. “Bununla birlikte ‘Çünkü Baba’ya gidiyorum’ diyor."],["18","‘Kısa bir süre’ söylediği bu nedir? Ne dediğini anlamıyoruz” dediler."],["19","Yeşua kendisine soru sormak istediklerini anladı ve onlara, “‘Kısa bir süre sonra beni görmeyeceksiniz ve yine kısa bir süre sonra beni göreceksiniz’ dediğim bu sözümü mü tartışıyorsunuz?"],["20","Size doğrusunu söyleyeyim, siz ağlayıp yas tutacaksınız, ama dünya sevinecek. Kederleneceksiniz ama kederiniz sevince dönecektir."],["21","Kadın doğum vakti ağrı çeker. Çünkü zamanı gelmiştir. Ama doğurduktan sonra, dünyaya bir insan doğması sevinciyle çektiği acıyı hatırlamaz."],["22","Sizin de şimdi kederiniz var. Ama sizi yeniden göreceğim ve yüreğiniz sevinecektir. Sevincinizi kimse sizden alamaz” dedi."],["23","“O gün gelince bana hiçbir soru sormayacaksınız. Size doğrusunu söyleyeyim, benim adımla Baba’dan ne dilerseniz, onu size verecektir."],["24","Şimdiye dek benim adımla hiçbir şey dilemediniz. Dileyin ve alacaksınız, öyle ki sevinciniz tam olsun."],["25","Bu şeyleri size benzetmelerle anlattım. Ama benzetmelerle konuşmayacağım, size Baba’yı açıkça anlatacağım zaman geliyor."],["26","O gün benim adımla dileyeceksiniz. Sizin için Baba’ya dua edeceğimi söylemiyorum."],["27","Çünkü Baba kendisi sizi seviyor; çünkü beni sevdiniz ve benim Baba’dan geldiğime iman ettiniz."],["28","Ben Baba’dan dünyaya geldim. Yine dünyadan ayrılıp Baba’ya dönüyorum.”"],["29","Öğrencileri O’na, “Bak, şimdi açıkça konuşuyorsun, hiç benzetmeler kullanmıyorsun” dediler."],["30","“Artık senin her şeyi bildiğini ve kimsenin sana soru sormasına gerek olmadığını anlıyoruz. Bu nedenle Tanrı’dan geldiğine iman ediyoruz.”"],["31","Yeşua onlara şu karşılığı verdi: “Şimdi iman ediyor musunuz?"],["32","İşte, şimdi, hepinizin kendi yerine gitmek üzere dağılacağı ve beni yalnız bırakacağınız zaman geliyor, evet geldi bile. Ama ben yalnız değilim, çünkü Baba benimle birliktedir."],["33","Bu şeyleri size, bende esenliğiniz olsun diye söyledim. Dünyada sıkıntınız olacak. Ama cesur olun, ben dünyaya galip geldim!”"]],17:[["1","Yeşua bunları söyledikten sonra gözlerini göğe kaldırıp, “Baba, zaman geldi” dedi. “Oğlun’u yücelt ki, Oğlun da seni yüceltsin."],["2","O’na tüm insanlık üzerinde yetki verdin. Öyle ki, O da kendisine verdiklerinin hepsine sonsuz hayat versin."],["3","Sonsuz hayat, tek gerçek Tanrı olan seni ve gönderdiğin Yeşua Mesih’i bilmeleridir."],["4","Seni yeryüzünde yücelttim. Yapmam için bana verdiğin işi tamamladım."],["5","Şimdi, Baba, dünya var olmadan önce seninleyken sahip olduğum yücelikle beni yanında yücelt."],["6","Adını dünyadan bana verdiğin insanlara açıkladım. Onlar senindi, sen onları bana verdin ve sözünü tuttular."],["7","Şimdi bana verdiğin her şeyin senden olduğunu biliyorlar."],["8","Çünkü bana verdiğin sözleri onlara verdim. Onlar da kabul ettiler. Senden geldiğimi gerçekten biliyorlar. Onlar beni senin gönderdiğine iman ettiler."],["9","Onlar için dua ediyorum. Dünya için değil, bana verdiklerin için dua ediyorum. Çünkü onlar senindir."],["10","Benim olan her şey senindir, seninkiler de benim. Ve ben onlarda yüceltildim."],["11","Ben artık dünyada değilim, ama bunlar dünyadadır. Ben sana geliyorum. Kutsal Baba, onları bana verdiğin adınla koru ki, bizim gibi bir olsunlar."],["12","Dünyada onlarla birlikteyken, adınla onları korudum. Bana verdiklerini korudum. Kutsal Yazı yerine gelsin diye, mahv oğlundan başkası mahvolmadı."],["13","Ama şimdi sana geliyorum ve sevincim onlarda tamamlansın diye bunları dünyadayken söylüyorum."],["14","Onlara senin sözünü bildirdim. Dünya onlardan nefret etti, çünkü ben dünyadan olmadığım gibi onlar da dünyadan değiller."],["15","Onları dünyadan alman için değil, kötü olandan koruman için dua ediyorum."],["16","Ben dünyadan olmadığım gibi onlar da dünyadan değiller."],["17","Onları gerçeğinde kutsal kıl. Senin sözün gerçektir."],["18","Beni dünyaya gönderdiğin gibi, ben de onları dünyaya gönderdim."],["19","Onlar da gerçekte kutsal kılınsınlar diye, kendimi onların uğruna adıyorum."],["20","Yalnız onlar için değil, onların sözüyle bana iman edecek olanlar için de dua ediyorum."],["21","Hepsi bir olsunlar. Baba, senin bende, benim sende olduğum gibi, onlar da bizde bir olsunlar. Dünya da beni senin gönderdiğine iman etsin."],["22","Bana verdiğin yüceliği ben de onlara verdim. Öyle ki, bizim bir olduğumuz gibi onlar da bir olsunlar."],["23","Ben onlarda, sen bende olmak üzere tamamlanmış birlik içinde olsunlar ki, dünya beni senin gönderdiğini, beni sevdiğin gibi onları da sevdiğini bilsin."],["24","Baba, bana verdiğin kişilerin de bulunduğum yerde benimle birlikte olmalarını istiyorum. Öyle ki, bana vermiş olduğun yüceliğimi görsünler. Çünkü sen beni dünyanın kuruluşundan önce sevdin."],["25","Ey adil Baba, dünya seni bilmedi, ama ben seni biliyorum. Bunlar da beni senin gönderdiğini biliyorlar."],["26","Adını onlara bildirdim ve bildireceğim. Öyle ki, bana olan sevgin onlarda olsun, ben de onlarda olayım.”"]],18:[["1","Yeşua bu sözleri söyledikten sonra öğrencileriyle birlikte dışarı çıkıp Kidron Deresi’nin ötesine geçti. Orada bir bahçe vardı, kendisi ve öğrencileri bu bahçeye girdiler."],["2","O’na ihanet eden Yahuda da o yeri biliyordu. Çünkü Yeşua sık sık orada öğrencileriyle buluşurdu."],["3","Yahuda da başkâhinlerden ve Ferisilerden bir bölük asker ve görevliler alıp fenerler, meşaleler ve silahlarla oraya geldi."],["4","Yeşua başına gelecekleri bilerek dışarı çıktı ve onlara, “Kimi arıyorsunuz?” dedi."],["5","O’na, “Nazaretli Yeşua” diye yanıt verdiler. Yeşua onlara, “Ben O’yum” dedi. O’na ihanet eden Yahuda da onlarla birlikte duruyordu."],["6","Onlara, “Ben O’yum” deyince, geriye gidip yere düştüler."],["7","Bunun üzerine yine onlara, “Kimi arıyorsunuz?” diye sordu. “Nazaretli Yeşua” dediler."],["8","Yeşua, “Size benim dedim. Madem beni arıyorsunuz, bırakın bunları gitsinler!”"],["9","Söylediği, “Bana verdiklerinden hiçbirini kaybetmedim” sözü yerine gelsin diye böyle konuştu."],["10","Bunun üzerine Simon Petrus taşıdığı kılıcı çekti, başkâhinin Malkus adındaki hizmetkârının sağ kulağını kesti."],["11","O zaman Yeşua Petrus’a, “Kılıcı kınına koy” dedi. “Baba’nın bana verdiği kâseden gerçekten içmeyeyim mi?”"],["12","Böylece komutanla buyruğundaki asker bölüğü ve Yahudi görevliler Yeşua’yı tutup bağladılar."],["13","O’nu ilk olarak, o yıl başkâhin olan Kayafa’nın kayınbabası Hanan’a götürdüler."],["14","Yahudiler'e halkın yararına bir tek adamın ölmesinin daha uygun olacağını öğütleyen Kayafa’ydı."],["15","Simon Petrus, başka bir öğrenciyle birlikte Yeşua’nın ardından gidiyordu. Bu öğrenci başkâhinin tanıdığı olduğundan Yeşua’yla birlikte başkâhinin avlusuna girdi;"],["16","Petrus dışarıda kapının yanında duruyordu. Başkâhinin tanıdığı diğer öğrenci dışarı çıkıp kapıyı tutan hizmetçi kızla konuştu ve Petrus’u içeri getirdi."],["17","Kapıyı tutan kız Petrus’a, “Sen de bu adamın öğrencilerinden biri değil misin?” dedi. Petrus, “Değilim” dedi."],["18","Hizmetkârlar ve nöbetçiler kömür ateşi yakmış duruyorlardı, çünkü hava soğuktu. Petrus'da onlarla birlikte durmuş ısınıyordu."],["19","Bunun üzerine başkâhin Yeşua’ya öğrencileri ve öğretisi hakkında sorular sordu."],["20","Yeşua ona şu karşılığı verdi: “Ben dünyaya açıkça konuştum. Her zaman havralarda ve bütün Yahudiler’in toplandıkları tapınakta öğrettim. Gizli bir şey söylemedim."],["21","Neden beni sorguluyorsunuz? Kendilerine ne söylediğimi beni işitenlere sorun. İşte, onlar söylediğim şeyleri biliyorlar.”"],["22","Yeşua bunu söyleyince, yanında duran görevlilerden biri, “Başkâhine böyle mi yanıt veriyorsun?” diyerek O’na bir tokat attı."],["23","Yeşua ona, “Eğer kötü söyledimse, kötülüğüne tanıklık et!” dedi. “Ancak iyiyse, neden bana vuruyorsun?”"],["24","Hanan O’nu bağlı olarak başkâhin Kayafa’ya gönderdi."],["25","Simon Petrus ayakta durmuş ısınıyordu. Ona, “Sen de O'nun öğrencilerinden birisin değil mi?” dediler. Petrus, “Değilim” diyerek inkâr etti."],["26","Başkâhinin hizmetkârlarından biri, Petrus’un kulağını kestiği kişinin akrabasıydı. Bu hizmetkâr, “Seni bahçede O’nunla birlikte görmedim mi?” dedi."],["27","Petrus yine inkâr etti ve hemen horoz öttü."],["28","Yeşua’yı Kayafa’nın yanından alıp vali konağına götürdüler. Sabah erkendi, Yahudi yetkililer dinsel açıdan kendilerini kirletmemek ve Pesah yemeğini yiyebilmek için vali konağına girmediler."],["29","Bu nedenle Pilatus dışarı çıkıp onların yanına geldi. “Bu adamı neyle suçluyorsunuz?” dedi."],["30","Ona, “Bu adam kötülük eden biri olmasaydı, O’nu sana getirmezdik” diye karşılık verdiler."],["31","Bunun üzerine Pilatus onlara, “O'nu alın ve kendi yasanıza göre yargılayın” dedi. Yahudi yetkililer, “Bizim kimseyi ölüm cezasına çarptırmamız yasal değildir” dediler."],["32","Öyle ki bu, Yeşua’nın ne tür bir ölümle öleceğini işaret etmiş olduğu sözü yerine gelsin diye oldu."],["33","Bunun üzerine Pilatus yeniden vali konağına girdi. Yeşua’yı çağırıp O’na, “Sen Yahudiler’in Kralı mısın?” diye sordu."],["34","Yeşua ona, “Bunu kendiliğinden mi söylüyorsun, yoksa başkaları mı benim için sana dediler?” dedi."],["35","Pilatus, “Ben Yahudi miyim? Kendi ulusun ve başkâhinler seni bana teslim ettiler. Ne yaptın?” dedi."],["36","Yeşua, “Benim krallığım bu dünyadan değil. Eğer krallığım bu dünyadan olsaydı, o zaman hizmetkârlarım Yahudiler'e teslim edilmeyeyim diye savaşırlardı. Ama benim krallığım buradan değil” karşılığını verdi."],["37","Bunun üzerine Pilatus O’na, “Öyleyse bir kral mısın?” dedi. Yeşua, “Kral olduğumu sen söylüyorsun. Ben bunun için doğdum, gerçeğe tanıklık etmek için dünyaya geldim. Gerçekten olan herkes sesimi duyar” karşılığını verdi."],["38","Pilatus O’na, “Gerçek nedir?” dedi. Bunu söyledikten sonra Pilatus yine dışarıya, Yahudiler'in yanına gidip onlara, “Ben O’nu suçlayacak hiçbir dayanak bulmuyorum” dedi."],["39","“Ama sizin bir adetiniz var, her Pesah'da sizin için birini salıvermeliyim. Bu nedenle, size Yahudiler’in Kralı’nı salıvermemi ister misiniz?”"],["40","Sonra hepsi bir ağızdan, “Bu adamı değil, Barabba’yı” diyerek yeniden bağırdılar. Oysa Barabba bir hayduttu."]],19:[["1","Bunun üzerine, Pilatus Yeşua’yı tutup kamçılattı."],["2","Askerler dikenlerden bir taç örüp başına koydular. O’na mor bir giysi giydirdiler."],["3","“Selam, ey Yahudiler’in Kralı!” diyorlar, yüzüne tokat atıyorlardı."],["4","Pilatus yine dışarı çıkıp onlara, “İşte, kendisinde hiçbir suç bulmadığımı bilesiniz diye O’nu size getiriyorum” dedi."],["5","Böylece Yeşua, başında dikenli taç ve üstündeki mor giysiyle dışarı çıktı. Pilatus onlara, “İşte, o adam!” dedi."],["6","Başkâhinler ve görevliler O’nu görünce, “Çarmıha ger! Çarmıha ger!” diye bağırdılar. Pilatus onlara, “O’nu kendiniz alıp çarmıha gerin” dedi. “Çünkü ben O’nu suçlamak için hiçbir dayanak bulmuyorum.”"],["7","Yahudiler ona, “Bizim bir yasamız var ve bu yasaya göre O’nun ölmesi gerekiyor. Çünkü kendini Tanrı’nın Oğlu yaptı” diye karşılık verdiler."],["8","Pilatus bu sözü duyunca daha çok korktu."],["9","Yine vali konağına girip Yeşua’ya, “Sen neredensin?” dedi. Ama Yeşua ona yanıt vermedi."],["10","O zaman Pilatus, “Bana karşılık vermeyecek misin? Seni salıvermeye de, çarmıha germeye de gücüm olduğunu bilmiyor musun?” dedi."],["11","Yeşua, “Sana yukarıdan verilmeseydi, benim üzerimde hiçbir gücün olmazdı” diye karşılık verdi. “Bu yüzden beni sana teslim edenin günahı daha büyüktür.”"],["12","Bunun için Pilatus O’nu salıvermek istedi. Ama Yahudiler bağırıp şöyle dediler, “Bu adamı salıverirsen, Sezar’ın dostu değilsin! Kendini kral yapan herkes Sezar’a karşı konuşur!” diye bağırdılar."],["13","Pilatus bu sözleri duyunca, Yeşua’yı dışarı çıkardı. Taş Döşeme, İbranice’de “Gabbata” denilen yerde yargı kürsüsüne oturdu."],["14","Pesah'ın Hazırlık Günü’ydü. Altıncı vakit sularıydı. Yahudiler’e, “İşte, Kralınız!” dedi."],["15","Onlar, “Uzaklaştır O'nu! Uzaklaştır O'nu! O’nu çarmıha ger!” diye bağırdılar. Pilatus onlara, “Kralınızı çarmıha gereyim mi?” dedi. Başkâhinler, “Bizim Sezar’dan başka kralımız yok!” diye karşılık verdiler."],["16","Sonunda Pilatus Yeşua’yı, çarmıha gerilmek üzere onlara teslim etti. Böylece O’nu alıp götürdüler."],["17","Yeşua çarmıhını kendisi taşıyarak Kafatası -İbranice’de Golgota- denilen yere çıktı."],["18","Orada O’nu ve iki kişiyi daha çarmıha gerdiler. Biri bir yanda, öbürü diğer yanda, Yeşua ise ortadaydı."],["19","Pilatus bir yafta da yazıp çarmı üzerine koydu. “NASIRALI YEŞUA - YAHUDİLER’İN KRALI” yazıyordu."],["20","İbranice, Latince ve Grekçe yazılan bu yazıyı Yahudiler’in birçoğu okudu. Çünkü Yeşua’nın çarmıha gerildiği yer kente yakındı."],["21","Bu nedenle Yahudi başkâhinler Pilatus’a, “‘Yahudiler’in Kralı’ diye yazma” dediler. “Kendisi ‘Ben Yahudiler’in Kralı’yım dedi’ diye yaz.”"],["22","Pilatus, “Ne yazdıysam yazdım” diye karşılık verdi."],["23","Askerler, Yeşua’yı çarmıha gerdikten sonra giysilerini aldılar. Her birine bir pay düşecek şekilde dört parçaya böldüler. Üstlüğünü de aldılar. Üstlüğü tek parçadan oluşan dikişsiz bir dokumaydı."],["24","Sonra birbirlerine, “Bunu yırtmayalım, kimin olacağına karar vermek için kura çekelim” dediler. Böylelikle şöyle diyen Kutsal Yazı yerine gelmiş oldu: “Örtümü aralarında paylaştılar. Giysimin üzerine kura çektiler.” Bunu yapan askerlerdi."],["25","Yeşua’nın çarmıhının yanında annesi, teyzesi, Klopas’ın karısı Mariyam ve Magdalalı Mariyam duruyordu."],["26","Yeşua, annesiyle sevdiği öğrencisinin orada durduğunu görünce annesine, “Kadın, işte oğlun!” dedi."],["27","Sonra öğrenciye, “İşte annen!” dedi. O saatten itibaren bu öğrenci onu kendi evine aldı."],["28","Bundan sonra Yeşua, her şeyin artık tamamlandığını görerek, Kutsal Yazı yerine gelsin diye, “Susadım” dedi."],["29","Orada sirke dolu bir kap konulmuştu. Sirke ile süngeri doldurup mercanköşküne takarak ağzına tuttular."],["30","Yeşua sirkeyi alınca, “Tamamlandı” dedi. O zaman başını eğip ruhunu teslim etti."],["31","Bunun üzerine Yahudiler, Hazırlık Günü olması nedeniyle, cesetlerin Şabat'da çarmıhta kalmasını istemiyorlardı. Pilatus’tan çarmıha gerilenlerin bacaklarının kırılmasını ve cesetlerinin kaldırılmasını istediler. Çünkü o Şabat büyük olanıydı."],["32","O zaman askerler gelip birinci adamın ve O'nunla birlikte çarmıha gerilmiş olan öbür adamın bacaklarını kırdılar."],["33","Ama Yeşua’nın yanına geldiklerinde O’nu çoktan ölmüş olduğunu görünce bacaklarını kırmadılar."],["34","Yine de askerlerden biri mızrakla böğrünü deldi. Yeşua’nın böğründen hemen kan ve su aktı."],["35","Bunu görmüş olan adam tanıklık etmiştir ve tanıklığı doğrudur. Kendisi doğruyu söylediğini bilir, taki, siz de iman edesiniz."],["36","Çünkü bu şeyler, “O'nun hiçbir kemiği kırılmayacak” diyen Kutsal Yazı yerine gelsin diye oldu."],["37","Yine başka bir Yazı’da, “Bedenini deştiklerine bakacaklar” der."],["38","Bu şeylerden sonra, Yeşua’nın öğrencisi olup Yahudiler'den korktuğu için kendini gizleyen Aramatyalı Yosef, Yeşua’nın cesedini kaldırmak için Pilatus’tan istekte bulundu. Pilatus izin verdi. Yosef gelip Yeşua’nın cesedini kaldırdı."],["39","Önceden gece vakti Yeşua’nın yanına gelmiş olan Nikodim de otuz litre kadar karışık mür ve sarısabır özü getirdi."],["40","Böylece Yeşua’nın cesedini alıp Yahudiler’in ölü gömme geleneğine göre baharatlarla keten beze sardılar."],["41","Yeşua’nın çarmıha gerildiği yerde bir bahçe vardı. Bu bahçede henüz hiç kimsenin gömülmediği yeni bir mezar vardı."],["42","O zaman Yahudiler’in Hazırlık Günü’ydü. Mezar da yakın olması nedeniyle Yeşua’yı oraya yatırdılar."]],20:[["1","Haftanın ilk günü erkenden, hava hâlâ karanlıkken Magdalalı Mariyam mezara gitti. Taşın mezardan kaldırılmış olduğunu gördü."],["2","Bunun üzerine koşup Simon Petrus’a ve Yeşua’nın sevdiği diğer öğrenciye geldi. Onlara, “Efendimiz’i mezardan almışlar ve nereye koyduklarını bilmiyoruz!” dedi."],["3","Bunun üzerine Petrus’la öteki öğrenci çıkıp mezara doğru gittiler."],["4","İkisi birlikte koşuyorlardı. Diğer öğrenci Petrus’u geride bırakıp mezara ilk gelen oldu."],["5","Eğilip içeri baktığında keten bezlerin yerde serili olduğunu gördü ama içeri girmedi."],["6","Sonra Simon Petrus onun ardından geldi ve mezara girdi. Serili duran keten bezleri gördü."],["7","Yeşua’nın başına sarılmış olan peşkir de oradaydı. Peşkir keten bezlerle birlikte değildi, ayrı bir yerde sarılmış duruyordu."],["8","O zaman mezara ilk gelen diğer öğrenci de içeri girip gördü ve iman etti."],["9","Çünkü Yeşua’nın ölümden dirilmesi gerektiğine ilişkin Kutsal Yazı’yı henüz bilmiyorlardı."],["10","Böylece öğrenciler yine kendi evlerine döndüler."],["11","Mariyam dışarıda, mezarın başında durmuş ağlıyordu. Ağlarken eğilip mezarın içine baktı."],["12","Yeşua’nın bedeninin yattığı yerde, biri başında, biri ayaklarında oturan beyazlar içinde iki melek gördü."],["13","Ona, “Kadın, niçin ağlıyorsun?” diye sordular. Onlara, “Çünkü Efendim’i alıp götürmüşler ve O’nu nereye koyduklarını bilmiyorum” dedi."],["14","Bunu söyledikten sonra arkasına döndü ve Yeşua’nın durduğunu gördü. O’nun Yeşua olduğunu bilmiyordu."],["15","Yeşua ona, “Kadın, niçin ağlıyorsun? Kimi arıyorsun?” dedi. O’nu bahçıvan sanıp, “Efendim, eğer O’nu sen alıp götürdüysen, nereye koyduğunu bana söyle de gidip O’nu alayım” dedi."],["16","Yeşua ona, “Mariyam!” dedi. Mariyam döndü ve O’na, “Rabbuni!” dedi. Öğretmenim demektir."],["17","Yeşua ona, “Bana dokunma! Çünkü henüz Babam’ın yanına çıkmadım. Ama kardeşlerime git ve onlara de ki, ‘Benim Babam’ın ve sizin Babanız’ın, benim Tanrım’ın ve sizin Tanrınız’ın yanına çıkıyorum’” dedi."],["18","Magdalalı Mariyam öğrencilere gelip Efendi’yi gördüğünü ve Efendi’nin kendisine bu şeyleri söylediğini onlara bildirdi."],["19","Haftanın o ilk günü akşam olunca, öğrenciler Yahudiler'den korktukları için bulundukları yerin kapıları kilitli vaziyette toplanmışlardı. Yeşua gelip ortada durdu ve onlara “Size esenlik olsun!” dedi."],["20","Bunu söyledikten sonra onlara ellerini ve böğrünü gösterdi. Öğrenciler Efendi’yi görünce sevindiler."],["21","Yeşua bunun üzerine yine onlara, “Size esenlik olsun!” dedi. “Baba beni nasıl gönderdiyse, ben de sizi gönderiyorum.”"],["22","Bunu söyledikten sonra üzerlerine üfleyerek onlara şöyle dedi, “Kutsal Ruh’u alın!"],["23","Kimin günahlarını bağışlarsanız, bağışlanmış olur. Kimin günahlarını alıkoyarsanız, alıkonmuş olur.”"],["24","Ancak Onikiler’den biri olup “Didimos” denilen Tomas, Yeşua geldiğinde yanlarında değildi."],["25","Bunun üzerine diğer öğrenciler ona, “Biz Efendi’yi gördük!” dediler. Ama Tomas onlara, “Ellerindeki çivilerin izini görmedikçe, çivilerin deldiği yerlere parmağımla dokunmadıkça ve elimi O’nun böğrüne sokmadıkça, inanmam” dedi."],["26","Aradan sekiz gün geçmişti. Yeşua’nın öğrencileri yine içerideydi ve Tomas da onlarla birlikteydi. Kapılar kilitliyken Yeşua gelip ortada durdu. “Size esenlik olsun” dedi."],["27","Sonra Tomas’a, “Parmağını buraya uzat ve ellerimi gör” dedi. “Elini uzat böğrüme koy. İnançsızlık etme, inan!”"],["28","Tomas O’na, “Efendim ve Tanrım!” diye yanıt verdi."],["29","Yeşua ona, “Beni gördüğün için mi iman ettin?” dedi. “Görmeden iman edenlere ne mutlu.”"],["30","Yeşua, öğrencilerinin önünde bu kitapta yazılı olmayan daha birçok belirtiler yaptı."],["31","Ama bunlar, Yeşua’nın Tanrı’nın Oğlu Mesih olduğuna iman edesiniz ve iman ederek O’nun adıyla hayata sahip olasınız diye yazılmıştır."]],21:[["1","Bu şeylerden sonra Yeşua, Taberiye Denizi’nin kıyısında öğrencilerine yine kendisini gösterdi. O kendisini böyle gösterdi."],["2","Simon Petrus, “Didimos” denilen Tomas, Galile Kana’lı Natanel, Zebedi’nin oğulları ve diğer iki öğrencisi birlikteydiler."],["3","Simon Petrus onlara, “Ben balık tutmaya gidiyorum” dedi. Diğerleri, “Biz de seninle geliyoruz” dediler. Hemen çıkıp tekneye bindiler. O gece hiçbir şey tutamadılar."],["4","Artık gün doğarken, Yeşua kıyıda duruyordu. Ancak öğrenciler O’nun Yeşua olduğunu bilmediler."],["5","O zaman Yeşua onlara, “Çocuklar, yiyecek bir şeyiniz var mı?” dedi. O’na “Hayır” diye yanıt verdiler."],["6","Onlara, “Ağı teknenin sağ tarafına atın, bir miktar bulacaksınız” dedi. Bunun üzerine, ağı attılar. Ama balık bolluğundan ağı çekemiyorlardı."],["7","O zaman Yeşua’nın sevdiği öğrenci Petrus’a, “Bu Efendi’dir!” dedi. Simon Petrus O’nun Efendi olduğunu duyunca üstlüğünü sarınıp (çünkü çıplaktı) denize atladı."],["8","Diğer öğrenciler de balık dolu ağı çekerek küçük bir tekneyle geldiler. Çünkü karadan uzakta değildiler, ancak iki yüz arşın açıkta idiler."],["9","Karaya çıktıklarında, orada kömür ateşi, ateşin üzerinde duran balık ve ekmek gördüler."],["10","Yeşua onlara, “Az önce tuttuğunuz şu balıklardan getirin” dedi."],["11","Simon Petrus tekneye çıktı ve tam yüz elli üç büyük balıkla dolu ağı karaya çekti. O kadar çok balık olmasına rağmen, ağ yırtılmamıştı."],["12","Yeşua onlara, “Gelin ve sabah yemeği yiyin!” dedi. Öğrencilerinden hiçbiri O’na, “Sen kimsin?” diye sormaya cesaret edemedi. Çünkü Efendi olduğunu biliyorlardı."],["13","Sonra Yeşua gidip ekmeği aldı, onlara verdi. Aynı şekilde balıkları da verdi."],["14","Bu, Yeşua’nın ölümden dirildikten sonra öğrencilerine üçüncü kez görünüşüydü."],["15","Böylece sabah yemeğini yedikten sonra Yeşua, Simon Petrus’a, “Ey Yona oğlu Simon, beni bunlardan daha çok seviyor musun?” dedi. Petrus, “Evet, Efendimiz, seni sevdiğimi biliyorsun” dedi. Ona, “Kuzularımı otlat” dedi."],["16","Ona ikinci kez, “Yona oğlu Simon, beni seviyor musun?” dedi. Petrus O'na, “Evet, Efendimiz, seni sevdiğimi biliyorsun” deyince, Yeşua ona, “Koyunlarıma bak” dedi."],["17","Ona üçüncü kez, “Yona oğlu Simon, beni seviyor musun?” dedi. Petrus, Yeşua’nın kendisine üçüncü kez “Beni seviyor musun?” diye sormasına kederlendi. O’na, “Efendimiz, sen her şeyi bilirsin. Seni sevdiğimi biliyorsun” dedi. Yeşua ona, “Koyunlarımı otlat."],["18","Sana doğrusunu söyleyeyim, gençken kendini giydirip, istediğin yere giderdin. Ama yaşlanınca ellerini uzatacaksın ve bir başkası seni giydirip gitmek istemediğin yere götürecek” dedi."],["19","Bunu, ne tür bir ölümle Tanrı’yı yücelteceğini işaret etmek için söyledi. Bunu söyledikten sonra ona, “Ardımdan gel” dedi."],["20","Sonra Petrus arkasını dönünce bir öğrencinin takip ettiğini gördü. Bu, Yeşua’nın sevdiği, akşam yemeğinde Yeşua’nın göğsüne yaslanmış, “Efendimiz, sana kim ihanet edecek?” diye soran öğrenciydi."],["21","Petrus onu görünce Yeşua’ya, “Efendimiz, bu adama ne olacak?” dedi."],["22","Yeşua ona, “Ben gelinceye dek onun kalmasını istiyorsam, bundan sana ne?” dedi. “Sen ardımdan gel.”"],["23","Bu nedenle, kardeşler arasında bu öğrencinin ölmeyeceğine dair bir söz çıktı. Ama Yeşua ona ölmeyeceğini söylememişti, “Eğer ben gelinceye dek kalmasını istiyorsam, bundan sana ne?” demişti."],["24","Bu şeylere tanıklık eden ve bu şeyleri yazan öğrenci budur. Biz onun tanıklığının doğru olduğunu biliyoruz."],["25","Yeşua’nın yaptığı başka çok şeyler daha vardı. Bunların hepsi bir bir yazılmış olsaydı, sanırım yazılan kitaplar dünyaya bile sığmazdı."]]};export{e as default};
